             "external",
             null
            ]
           },
           "criticised": {
            "type": [
             "boolean",
             "null"
            ]
           }
          },
          "description": "The observation is a CYCLE variant with the given cycle index, criticism source, and whether any field was criticised; each attribute is optional."
         },
         "verdict_move": {
          "type": "object",
          "additionalProperties": false,
          "required": [
           "from",
           "to"
          ],
          "properties": {
           "field": {
            "type": [
             "string",
             "null"
            ]
           },
           "from": {
            "anyOf": [
             {
              "type": "string"
             },
             {
              "type": "array",
              "minItems": 1,
              "items": {
               "type": "string"
              }
             }
            ]
           },
           "to": {
            "anyOf": [
             {
              "type": "string"
             },
             {
              "type": "array",
              "minItems": 1,
              "items": {
               "type": "string"
              }
             }
            ]
           },
           "criticised": {
            "type": [
             "boolean",
             "null"
            ]
           }
          },
          "description": "Some field (or the named one) had a verdict in `from` on the step this observation follows and a verdict in `to` here; `miss` stands for every criticising field verdict; `criticised` restricts to fields the cycle's criticism named (true) or did not (false)."
         },
           "endpoint": {
            "type": "object",
            "additionalProperties": false,
            "minProperties": 1,
            "properties": {
             "think": {
              "anyOf": [
               {
                "type": [
                 "boolean",
                 "null"
                ]
               },
               {
                "enum": [
                 "low",
                 "medium",
                 "high"
                ]
               }
              ]
             },
             "timeout_seconds": {
              "type": "integer",
              "minimum": 1
             }
            },
            "description": "A setting of the run the observation belongs to, read from its run record (the reasoning setting actually sent, the call timeout); false when the run record was not supplied."
           },
          "internal_count": {
           "type": "object",
           "additionalProperties": false,
           "required": [
            "field",
            "of",
            "value"
           ],
           "properties": {
            "field": {
             "type": "string"
            },
            "of": {
             "type": "array",
             "minItems": 1,
             "items": {
              "type": "string"
             }
            },
            "value": {
             "type": [
              "string",
              "integer",
              "boolean"
             ]
            }
           },
           "description": "A relation inside one reply: the integer in `field` equals the number of `of` fields whose value is `value`. False when a named field is absent or the count is not an integer; it never consults the answer key."
          },
         "criticised_field": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
           "changed": {
            "type": [
             "boolean",
             "null"
            ]
           },
           "verdict": {
            "anyOf": [
             {
              "type": "string"
             },
             {
              "type": "array",
              "minItems": 1,
              "items": {
               "type": "string"
              }
             },
             {
              "type": "null"
             }
            ]
           },
           "grounding_verdict": {
            "anyOf": [
             {
              "type": "string"
             },
             {
              "type": "array",
              "minItems": 1,
              "items": {
               "type": "string"
              }
             },
             {
              "type": "null"
             }
            ]
           }
          },
          "description": "Some field the cycle's criticism named satisfies every given condition: its value (or its companion span) changed or did not, its field verdict here is one of `verdict`, its grounding verdict here is one of `grounding_verdict`."
         },
        "output_tokens": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "min": {
              "type": [
                "integer",
                "null"
              ],
              "minimum": 0
            },
            "max": {
              "type": [
                "integer",
                "null"
              ],
              "minimum": 0
            }
          },
          "description": "The reply's generated token count (eval_count) within [min, max]; false when the record has no count."
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://ahepi.example/smf/0.5/conformance-corpus.schema.json",
  "title": "SMF-0.5 task-conformance case corpus",
  "description": "Case documents with per-field oracles. Every oracle carries a non-final status and a rationale; an oracle is a proposed expectation, never a ground truth.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "corpus_id",
    "cases"
  ],
  "properties": {
    "schema_version": {
      "const": "creib.conformance-pilot.corpus.v1"
    },
    "corpus_id": {
      "$ref": "#/$defs/identifier"
    },
    "cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/case"
      }
    }
  },
  "$defs": {
    "nonempty_string": {
      "type": "string",
      "minLength": 1,
      "pattern": ".*\\S.*"
    },
    "identifier": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
    },
    "field_name": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]{0,63}$"
    },
    "scalar": {
      "type": [
        "string",
        "boolean",
        "integer",
        "null"
      ]
    },
    "rendering": {
      "type": "string",
      "enum": [
        "prose",
        "table",
        "email"
      ]
    },
    "oracle_status": {
      "type": "string",
      "enum": [
        "source_scoped",
        "interpretation_provisional",
        "project_import_provisional"
      ]
    },
    "oracle_entry": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "field",
        "kind",
        "value",
        "values",
        "pattern",
        "oracle_status",
        "rationale"
      ],
      "properties": {
        "field": {
          "$ref": "#/$defs/field_name"
        },
        "kind": {
          "type": "string",
          "enum": [
            "exact",
            "regex",
            "enum",
            "absent",
            "any_of",
            "unknown"
          ]
        },
        "value": {
          "$ref": "#/$defs/scalar"
        },
        "values": {
          "type": [
            "array",
            "null"
          ],
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/scalar"
          }
        },
        "pattern": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1
        },
        "oracle_status": {
          "$ref": "#/$defs/oracle_status"
        },
        "rationale": {
          "$ref": "#/$defs/nonempty_string"
        }
      }
    },
    "field_value": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "field",
        "value"
      ],
      "properties": {
        "field": {
          "$ref": "#/$defs/field_name"
        },
        "value": {
          "$ref": "#/$defs/scalar"
        }
      }
    },
    "case": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "case_id",
        "boundary",
        "rendering",
        "renderings",
        "expected",
        "held_fixed",
        "varied",
        "pair_of",
        "reference_output",
        "rival_expected",
        "notes"
      ],
      "properties": {
        "case_id": {
          "$ref": "#/$defs/identifier"
        },
        "boundary": {
          "type": "boolean"
        },
        "rendering": {
          "$ref": "#/$defs/rendering"
        },
        "renderings": {
          "type": "object",
          "additionalProperties": false,
          "minProperties": 1,
          "properties": {
            "prose": {
              "$ref": "#/$defs/nonempty_string"
            },
            "table": {
              "$ref": "#/$defs/nonempty_string"
            },
            "email": {
              "$ref": "#/$defs/nonempty_string"
            }
          }
        },
        "expected": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/oracle_entry"
          }
        },
        "held_fixed": {
          "$ref": "#/$defs/nonempty_string"
        },
        "varied": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1
        },
        "pair_of": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
        },
        "reference_output": {
          "type": [
            "array",
            "null"
          ],
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/field_value"
          }
        },
        "rival_expected": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "field",
              "label",
              "oracle"
            ],
            "properties": {
              "field": {
                "$ref": "#/$defs/field_name"
              },
              "label": {
                "$ref": "#/$defs/identifier"
              },
              "oracle": {
                "$ref": "#/$defs/oracle_entry"
              },
              "also": {
                "type": "array",
                "description": "Readings of other fields the same rival rule fixes; scored in place of the baseline key under that rule.",
                "items": {
                  "$ref": "#/$defs/oracle_entry"
                }
              }
            }
          }
        },
        "notes": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://ahepi.example/smf/0.5/conformance-observation.schema.json",
  "title": "SMF-0.5 task-conformance observation",
  "description": "One executed variant: the exact request digest, the raw response, the plural-verdict scoring, and the plural failure routing. An observation never confirms a model; an empty live-locus set means only that this one variant did not refute the declared expectation.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "observation_id",
    "run_id",
    "pilot_id",
    "plan_id",
    "planned_variant_id",
    "spec_bindings",
    "model",
    "variant",
    "request_digest",
    "response",
    "scoring",
    "routing",
    "baseline_observation_id",
    "replayed_from",
    "created_on"
  ],
  "properties": {
    "schema_version": {
      "const": "creib.conformance-pilot.observation.v3"
    },
    "observation_id": {
      "$ref": "#/$defs/hex_digest"
    },
    "run_id": {
      "$ref": "#/$defs/hex_digest"
    },
    "pilot_id": {
      "$ref": "#/$defs/identifier"
    },
    "plan_id": {
      "$ref": "#/$defs/hex_digest"
    },
    "planned_variant_id": {
      "$ref": "#/$defs/hex_digest"
    },
    "spec_bindings": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/binding"
      }
    },
    "model": {
      "$ref": "#/$defs/model_id"
    },
    "variant": {
      "$ref": "#/$defs/variant"
    },
    "request_digest": {
      "type": [
        "string",
        "null"
      ],
      "pattern": "^sha256:[0-9a-f]{64}$"
    },
    "response": {
      "oneOf": [
        {
          "$ref": "#/$defs/response"
        },
        {
          "type": "null"
        }
      ]
    },
    "scoring": {
      "$ref": "#/$defs/scoring"
    },
    "routing": {
      "$ref": "#/$defs/routing"
    },
    "baseline_observation_id": {
      "type": [
        "string",
        "null"
      ],
      "pattern": "^[0-9a-f]{64}$"
    },
    "replayed_from": {
      "type": [
        "string",
        "null"
      ],
      "pattern": "^[0-9a-f]{64}$",
      "description": "v3: for a replay run, the id of the observation whose recorded reply this one re-scores; null for a live call. A claims evaluation refuses a reply and its replay together."
    },
    "created_on": {
      "$ref": "#/$defs/rfc3339"
    }
  },
  "$defs": {
    "nonempty_string": {
      "type": "string",
      "minLength": 1,
      "pattern": ".*\\S.*"
    },
    "identifier": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
    },
    "sentence_id": {
      "type": "string",
      "pattern": "^S[1-9][0-9]{0,3}$"
    },
    "field_name": {
      "type": "string",
      "maxLength": 256
    },
    "model_id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}$"
    },
    "hex_digest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    },
    "rfc3339": {
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(Z|[+-][0-9]{2}:[0-9]{2})$"
    },
    "scalar": {
      "type": [
        "string",
        "boolean",
        "integer",
        "null"
      ]
    },
    "binding": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "path",
        "sha256"
      ],
      "properties": {
        "path": {
          "type": "string",
          "minLength": 1,
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._/-]{0,255}$"
        },
        "sha256": {
          "$ref": "#/$defs/hex_digest"
        }
      }
    },
    "family": {
      "type": "string",
      "enum": [
        "BASELINE",
        "DELETION",
        "NEGATION",
        "RIVAL_SUBSTITUTION",
        "SEMANTIC_ROLE_TWIN",
        "SUBSTRATE_SWAP",
        "BOUNDARY_SHIFT",
        "IMPORT_DEPENDENCY",
        "NON_VACUITY",
        "ROUND_TRIP",
        "REPEAT",
        "CYCLE",
        "UNIT_DEPENDENCE"
      ]
    },
    "oracle_status": {
      "type": "string",
      "enum": [
        "source_scoped",
        "interpretation_provisional",
        "project_import_provisional"
      ]
    },
    "oracle_entry": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "field",
        "kind",
        "value",
        "values",
        "pattern",
        "oracle_status",
        "rationale"
      ],
      "properties": {
        "field": {
          "$ref": "#/$defs/field_name"
        },
        "kind": {
          "type": "string",
          "enum": [
            "exact",
            "regex",
            "enum",
            "absent",
            "any_of",
            "unknown"
          ]
        },
        "value": {
          "$ref": "#/$defs/scalar"
        },
        "values": {
          "type": [
            "array",
            "null"
          ],
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/scalar"
          }
        },
        "pattern": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1
        },
        "oracle_status": {
          "$ref": "#/$defs/oracle_status"
        },
        "rationale": {
          "$ref": "#/$defs/nonempty_string"
        }
      }
    },
    "field_value": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "field",
        "value"
      ],
      "properties": {
        "field": {
          "$ref": "#/$defs/field_name"
        },
        "value": {
          "$ref": "#/$defs/scalar"
        }
      }
    },
    "field_schema": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "string",
            "boolean",
            "integer",
            "array"
          ]
        },
        "description": {
          "$ref": "#/$defs/nonempty_string"
        },
        "pattern": {
          "$ref": "#/$defs/nonempty_string"
        },
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "type"
          ],
          "properties": {
            "type": {
              "const": "string"
            },
            "enum": {
              "type": "array",
              "minItems": 1,
              "uniqueItems": true,
              "items": {
                "type": "string"
              }
            }
          },
          "description": "Array fields only: every item is a string, optionally from a closed list."
        },
        "uniqueItems": {
          "type": "boolean"
        },
        "minItems": {
          "type": "integer",
          "minimum": 0
        },
        "maxItems": {
          "type": "integer",
          "minimum": 0
        },
        "enum": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string"
          }
        },
        "maxLength": {
          "type": "integer",
          "minimum": 0
        },
        "minLength": {
          "type": "integer",
          "minimum": 0
        },
        "format": {
          "$ref": "#/$defs/nonempty_string"
        }
      }
    },
    "form_schema": {
      "description": "The restricted JSON Schema profile a pilot form may use. The properties map is the one place where keys are data (field names); every field schema is itself closed.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "type",
        "additionalProperties",
        "required",
        "properties"
      ],
      "properties": {
        "$schema": {
          "const": "https://json-schema.org/draft/2020-12/schema"
        },
        "title": {
          "$ref": "#/$defs/nonempty_string"
        },
        "description": {
          "$ref": "#/$defs/nonempty_string"
        },
        "type": {
          "const": "object"
        },
        "additionalProperties": {
          "const": false
        },
        "required": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "properties": {
          "type": "object",
          "minProperties": 1,
          "propertyNames": {
            "pattern": "^[a-z][a-z0-9_]{0,63}$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/field_schema"
          }
        }
      }
    },
    "variant": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "variant_id",
        "family",
        "base_case_id",
        "form_schema",
        "field_order",
        "instructions",
        "input_document",
        "expected",
        "held_fixed",
        "controlled_difference",
        "expectation_kind",
        "substrate",
        "control_id",
        "control_output",
        "model_call",
        "round_trip_of",
        "rival_label",
        "removed_sentence_id",
        "grounding"
      ],
      "properties": {
        "variant_id": {
          "$ref": "#/$defs/hex_digest"
        },
        "family": {
          "$ref": "#/$defs/family"
        },
        "base_case_id": {
          "$ref": "#/$defs/identifier"
        },
        "form_schema": {
          "$ref": "#/$defs/form_schema"
        },
        "field_order": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "instructions": {
          "$ref": "#/$defs/nonempty_string"
        },
        "input_document": {
          "type": [
            "string",
            "null"
          ]
        },
        "expected": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/oracle_entry"
          }
        },
        "held_fixed": {
          "$ref": "#/$defs/nonempty_string"
        },
        "controlled_difference": {
          "$ref": "#/$defs/nonempty_string"
        },
        "expectation_kind": {
          "type": "string",
          "enum": [
            "ORACLE",
            "RECORD_DEPENDENCE",
            "ROUND_TRIP",
            "CONTROL_REJECT",
            "CONTROL_ACCEPT"
          ]
        },
        "substrate": {
          "type": [
            "string",
            "null"
          ],
          "enum": [
            "prose",
            "table",
            "email",
            null
          ]
        },
        "control_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
        },
        "control_output": {
          "type": [
            "array",
            "null"
          ],
          "items": {
            "$ref": "#/$defs/field_value"
          }
        },
        "model_call": {
          "type": "boolean"
        },
        "round_trip_of": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[0-9a-f]{64}$"
        },
        "rival_label": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
        },
        "removed_sentence_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^S[1-9][0-9]{0,3}$"
        },
        "grounding": {
          "oneOf": [
            {
              "type": "null"
            },
            {
              "$ref": "#/$defs/grounding_config"
            }
          ]
        },
        "repeat_index": {
          "type": "integer",
          "minimum": 1,
          "description": "REPEAT only: which repetition of the baseline request this is. Absent for every other family."
        },
        "cycle_index": {
          "type": "integer",
          "minimum": 1,
          "description": "CYCLE only: which cycle after the baseline this is. Absent for every other family, and the four keys below are present exactly when it is."
        },
        "cycle_criticism": {
          "enum": [
            "none",
            "external"
          ],
          "description": "CYCLE only: what the model was shown beside its previous answer."
        },
        "cycle_of": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$",
          "description": "CYCLE only: the planned variant id of the step this cycle follows (the baseline for cycle 1)."
        },
        "cycle_previous_output": {
          "type": [
            "string",
            "null"
          ],
          "description": "CYCLE only: the previous answer shown to the model, as canonical JSON text; null on the planned variant, set on the materialised one."
        },
        "cycle_criticisms": {
          "type": [
            "array",
            "null"
          ],
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "field",
              "verdict",
              "detail"
            ],
