    "response",
    "scoring",
    "routing",
    "baseline_observation_id",
    "created_on"
  ],
  "properties": {
    "schema_version": {
      "const": "creib.conformance-pilot.observation.v2"
    },
    "observation_id": {
      "$ref": "#/$defs/hex_digest"
    },
    "run_id": {
      "$ref": "#/$defs/hex_digest"
    },
    "pilot_id": {
      "$ref": "#/$defs/identifier"
    },
    "plan_id": {
      "$ref": "#/$defs/hex_digest"
    },
