          "$ref": "#/$defs/family"
        },
        "base_case_id": {
          "$ref": "#/$defs/identifier"
        },
        "form_schema": {
          "$ref": "#/$defs/form_schema"
        },
        "field_order": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "instructions": {
          "$ref": "#/$defs/nonempty_string"
        },
        "input_document": {
          "type": [
            "string",
            "null"
          ]
        },
        "expected": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/oracle_entry"
          }
        },
        "held_fixed": {
          "$ref": "#/$defs/nonempty_string"
        },
        "controlled_difference": {
          "$ref": "#/$defs/nonempty_string"
        },
        "expectation_kind": {
          "type": "string",
          "enum": [
            "ORACLE",
            "RECORD_DEPENDENCE",
            "ROUND_TRIP",
            "CONTROL_REJECT",
            "CONTROL_ACCEPT"
          ]
        },
        "substrate": {
          "type": [
            "string",
            "null"
          ],
          "enum": [
            "prose",
            "table",
            "email",
            null
          ]
        },
        "control_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
        },
        "control_output": {
          "type": [
            "array",
            "null"
          ],
          "items": {
            "$ref": "#/$defs/field_value"
          }
        },
        "model_call": {
          "type": "boolean"
        },
        "round_trip_of": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[0-9a-f]{64}$"
        },
        "rival_label": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
        },
        "removed_sentence_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^S[1-9][0-9]{0,3}$"
        },
        "grounding": {
          "oneOf": [
            {
              "type": "null"
            },
            {
              "$ref": "#/$defs/grounding_config"
            }
          ]
        },
        "repeat_index": {
          "type": "integer",
          "minimum": 1,
          "description": "REPEAT only: which repetition of the baseline request this is. Absent for every other family."
        },
        "cycle_index": {
          "type": "integer",
          "minimum": 1,
          "description": "CYCLE only: which cycle after the baseline this is. Absent for every other family, and the four keys below are present exactly when it is."
        },
        "cycle_criticism": {
          "enum": [
            "none",
            "external"
          ],
          "description": "CYCLE only: what the model was shown beside its previous answer."
        },
        "cycle_of": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$",
          "description": "CYCLE only: the planned variant id of the step this cycle follows (the baseline for cycle 1)."
        },
        "cycle_previous_output": {
          "type": [
            "string",
            "null"
          ],
          "description": "CYCLE only: the previous answer shown to the model, as canonical JSON text; null on the planned variant, set on the materialised one."
        },
        "cycle_criticisms": {
          "type": [
            "array",
            "null"
          ],
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "field",
              "verdict",
              "detail"
            ],
            "properties": {
              "field": {
                "type": "string"
              },
              "verdict": {
                "enum": [
                  "MISSING_REQUIRED",
                  "EXTRA_FIELD",
                  "TYPE_VIOLATION",
                  "PATTERN_VIOLATION",
                  "ENUM_VIOLATION",
                  "LENGTH_VIOLATION",
                  "SPAN_MISSING",
                  "SPAN_NOT_IN_DOCUMENT",
                  "VALUE_NOT_IN_SPAN"
                ]
              },
              "detail": {
                "type": [
                  "string",
                  "null"
                ]
              }
            }
          },
          "description": "CYCLE only: the failed checks shown to the model with the previous answer; the vocabulary is the oracle-free one, so the answer key can never appear here. Empty for a self-revision cycle."
        },
        "removed_unit_id": {
          "type": "string",
          "minLength": 1,
          "description": "UNIT_DEPENDENCE only: the unit of the case document removed for this variant. Absent for every other family, and the three keys below are present exactly when it is."
        },
        "removed_unit_title": {
          "type": "string",
          "description": "The heading of the removed unit."
        },
        "removed_unit_relation": {
          "type": "string",
          "enum": ["self", "declared", "other"],
          "description": "The unit's relation to the claim the case preamble names, computed from the document by pattern: self (the document's own argument for the claim), declared (defines a term that argument uses), other."
        },
        "removed_unit_defines": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "The terms the removed unit is taken to define, by the same pattern heuristic; may be empty."
        }

      }
    },
    "response_attempt": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "content",
        "thinking_present",
        "done",
        "done_reason",
        "prompt_eval_count",
        "eval_count",
        "total_duration_ns",
        "http_status",
        "transport_error",
        "response_digest",
        "attempt"
      ],
      "properties": {
        "content": {
          "type": "string"
        },
        "thinking_present": {
          "type": "boolean"
        },
        "done": {
          "type": "boolean"
        },
        "done_reason": {
          "type": [
            "string",
            "null"
          ]
        },
        "prompt_eval_count": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        },
        "eval_count": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        },
        "total_duration_ns": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        },
        "http_status": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 100,
          "maximum": 599
        },
        "transport_error": {
          "type": [
            "string",
            "null"
          ]
        },
        "response_digest": {
          "$ref": "#/$defs/hex_digest"
        },
        "attempt": {
          "type": "integer",
          "minimum": 1
        }
      }
    },
    "response": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "content",
        "thinking_present",
        "done",
        "done_reason",
        "prompt_eval_count",
        "eval_count",
        "total_duration_ns",
        "http_status",
        "transport_error",
        "response_digest",
        "attempt",
        "prior_attempts"
      ],
      "properties": {
        "content": {
          "type": "string"
        },
        "thinking_present": {
          "type": "boolean"
        },
        "done": {
          "type": "boolean"
        },
        "done_reason": {
          "type": [
            "string",
            "null"
          ]
        },
        "prompt_eval_count": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        },
        "eval_count": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        },
        "total_duration_ns": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        },
        "http_status": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 100,
          "maximum": 599
        },
        "transport_error": {
          "type": [
            "string",
            "null"
          ]
        },
        "response_digest": {
          "$ref": "#/$defs/hex_digest"
        },
        "attempt": {
          "type": "integer",
          "minimum": 1
        },
        "prior_attempts": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/response_attempt"
          }
        }
      }
    },
    "response_verdict": {
      "type": "string",
      "enum": [
        "JSON_OBJECT",
        "TRANSPORT_ERROR",
        "EMPTY_RESPONSE",
        "TRUNCATED",
        "INVALID_JSON",
        "NOT_AN_OBJECT",
        "REFUSAL_SUSPECTED",
        "NO_MODEL_CALL",
        "PREREQUISITE_UNAVAILABLE"
      ]
    },
    "field_verdict_kind": {
      "type": "string",
      "enum": [
        "MATCH",
        "MISMATCH",
        "MISSING_REQUIRED",
        "EXTRA_FIELD",
        "TYPE_VIOLATION",
        "PATTERN_VIOLATION",
        "ENUM_VIOLATION",
        "LENGTH_VIOLATION",
        "UNEXPECTED_PRESENT",
        "NOT_SCORED"
      ]
    },
    "field_verdict": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "field",
        "verdict",
        "observed_present",
        "observed_canonical",
        "expected_summary",
        "oracle_status",
        "detail"
      ],
      "properties": {
        "field": {
          "type": "string",
          "maxLength": 256
        },
        "verdict": {
          "$ref": "#/$defs/field_verdict_kind"
        },
        "observed_present": {
          "type": "boolean"
        },
        "observed_canonical": {
          "type": [
            "string",
            "null"
          ]
        },
        "expected_summary": {
          "type": [
            "string",
            "null"
          ]
        },
        "oracle_status": {
          "oneOf": [
            {
              "$ref": "#/$defs/oracle_status"
            },
            {
              "type": "null"
            }
          ]
        },
        "detail": {
          "type": [
            "string",
            "null"
          ]
        }
      }
    },
    "scoring": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "response_verdict",
        "response_detail",
        "recovered_from_prose",
        "recovery_status",
        "parsed_output_canonical",
        "schema_valid",
        "field_verdicts",
        "changed_vs_baseline",
        "grounding_verdicts"
      ],
      "properties": {
        "response_verdict": {
          "$ref": "#/$defs/response_verdict"
        },
        "response_detail": {
          "type": [
            "string",
            "null"
          ]
        },
        "recovered_from_prose": {
          "type": "boolean"
        },
        "recovery_status": {
          "type": [
            "string",
            "null"
          ],
          "enum": [
            "project_import_provisional",
            null
          ]
        },
        "parsed_output_canonical": {
          "type": [
            "string",
            "null"
          ]
        },
        "schema_valid": {
          "type": [
            "boolean",
            "null"
          ]
        },
        "field_verdicts": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/field_verdict"
          }
        },
        "changed_vs_baseline": {
          "type": [
            "boolean",
            "null"
          ]
        },
        "grounding_verdicts": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/grounding_verdict"
          }
        }
      }
    },
    "trigger": {
      "type": "string",
      "enum": [
        "TRANSPORT_ERROR",
        "EMPTY_RESPONSE",
        "TRUNCATED",
        "INVALID_JSON",
        "NOT_AN_OBJECT",
        "REFUSAL_SUSPECTED",
        "PREREQUISITE_UNAVAILABLE",
        "MISMATCH",
        "MISSING_REQUIRED",
        "EXTRA_FIELD",
        "TYPE_VIOLATION",
        "PATTERN_VIOLATION",
        "ENUM_VIOLATION",
        "LENGTH_VIOLATION",
        "UNEXPECTED_PRESENT",
        "SCHEMA_INVALID",
        "IDENTICAL_TO_BASELINE",
        "CONTROL_ACCEPTED",
        "CONTROL_REJECTED",
        "DEPENDENCE_CHANGED",
        "DEPENDENCE_UNCHANGED",
        "FORMAT_NOT_ENFORCED",
        "SPAN_MISSING",
        "SPAN_NOT_IN_DOCUMENT",
        "VALUE_NOT_IN_SPAN",
        "REPEAT_DIFFERS"
      ]
    },
    "routing": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "live_loci",
        "route",
        "unrefuted_for_variant",
        "triggers",
        "format_enforced_by_server"
      ],
      "properties": {
        "live_loci": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "locus",
              "reason"
            ],
            "properties": {
              "locus": {
                "type": "string",
                "enum": [
                  "CANDIDATE",
                  "AUXILIARY",
                  "TEST",
                  "SCOPE"
                ]
              },
              "reason": {
                "$ref": "#/$defs/nonempty_string"
              }
            }
          }
        },
        "route": {
          "const": "AWAITING_HUMAN_TRIAGE"
        },
        "unrefuted_for_variant": {
          "type": "boolean"
        },
        "triggers": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/trigger"
          }
        },
        "format_enforced_by_server": {
          "type": [
            "boolean",
            "null"
          ]
        }
      }
    },
    "grounding_config": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "mode",
        "span_suffix",
        "span_fields",
        "value_in_span_fields",
        "abstain_fields"
      ],
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "none",
            "spans"
          ]
        },
        "span_suffix": {
          "type": "string",
          "pattern": "^_[a-z][a-z0-9_]{0,31}$"
        },
        "span_fields": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "value_in_span_fields": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "abstain_fields": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "span_relaxations": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "enum": [
              "case_insensitive",
              "date_range_completion"
            ]
          },
          "description": "Relaxations of the verbatim span match; absent means verbatim. Written only when non-empty."
        }
      }
    },
    "grounding_verdict": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "field",
        "verdict",
        "span",
        "detail"
      ],
      "properties": {
        "field": {
          "$ref": "#/$defs/field_name"
        },
        "verdict": {
          "type": "string",
          "enum": [
            "GROUNDED",
            "SPAN_MISSING",
            "SPAN_NOT_IN_DOCUMENT",
            "VALUE_NOT_IN_SPAN",
            "ABSTAINED"
          ]
        },
        "span": {
          "type": [
            "string",
            "null"
          ]
        },
        "detail": {
          "type": [
            "string",
            "null"
          ]
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://ahepi.example/smf/0.5/conformance-pilot-config.schema.json",
  "title": "SMF-0.5 task-conformance pilot configuration",
  "description": "Declares one form-filling conformance pilot: the form, the instructions, the corpus, the models, the endpoint, and the family-specific configuration. Nothing here is a verdict about any model.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "pilot_id",
    "title",
    "form_schema",
    "instructions",
    "corpus",
    "models",
    "endpoint",
    "charter",
    "load_bearing",
    "negations",
    "twins",
    "ambiguity",
    "controls",
    "refusal_phrases",
    "grounding",
    "repeats"
  ],
  "properties": {
    "schema_version": {
      "const": "creib.conformance-pilot.config.v1"
    },
    "pilot_id": {
      "$ref": "#/$defs/identifier"
    },
    "title": {
      "$ref": "#/$defs/nonempty_string"
    },
    "form_schema": {
      "$ref": "#/$defs/relative_path"
    },
    "instructions": {
      "$ref": "#/$defs/relative_path"
    },
    "corpus": {
      "$ref": "#/$defs/relative_path"
    },
    "models": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/model_id"
      }
    },
    "endpoint": {
      "$ref": "#/$defs/endpoint"
    },
    "charter": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "purpose",
        "output",
        "scope_in",
        "scope_out"
      ],
      "properties": {
        "purpose": {
          "$ref": "#/$defs/nonempty_string"
        },
        "output": {
          "$ref": "#/$defs/nonempty_string"
        },
        "scope_in": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/nonempty_string"
          }
        },
        "scope_out": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/nonempty_string"
          }
        }
      }
    },
    "load_bearing": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/sentence_id"
      }
    },
    "negations": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "field",
          "sentence_id",
          "replacement_sentence",
          "replacement_pattern",
          "value_transform"
        ],
        "properties": {
          "field": {
            "$ref": "#/$defs/field_name"
          },
          "sentence_id": {
            "$ref": "#/$defs/sentence_id"
          },
          "replacement_sentence": {
            "$ref": "#/$defs/nonempty_string"
          },
          "replacement_pattern": {
            "$ref": "#/$defs/nonempty_string"
          },
          "value_transform": {
            "type": "string",
            "enum": [
              "iso_date_to_dmy",
              "e164_au_to_national_spaced"
            ]
          }
        }
      }
    },
    "twins": {
      "type": "array",
      "items": {
        "type": "array",
        "minItems": 2,
        "maxItems": 2,
        "uniqueItems": true,
        "items": {
          "$ref": "#/$defs/field_name"
        }
      }
    },
    "ambiguity": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "field",
          "question",
          "rivals"
        ],
        "properties": {
          "field": {
            "$ref": "#/$defs/field_name"
          },
          "question": {
            "$ref": "#/$defs/nonempty_string"
          },
          "rivals": {
            "type": "array",
            "minItems": 2,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "label",
                "instruction"
              ],
              "properties": {
                "label": {
                  "$ref": "#/$defs/identifier"
                },
                "instruction": {
                  "$ref": "#/$defs/nonempty_string"
                }
              }
            }
          }
        }
      }
    },
    "controls": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "control_id",
          "corruption"
        ],
        "properties": {
          "control_id": {
            "$ref": "#/$defs/identifier"
          },
          "corruption": {
            "oneOf": [
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "kind"
                ],
                "properties": {
                  "kind": {
                    "const": "none"
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "kind",
                  "fields"
                ],
                "properties": {
                  "kind": {
                    "const": "swap_fields"
                  },
                  "fields": {
                    "type": "array",
                    "minItems": 2,
                    "maxItems": 2,
                    "uniqueItems": true,
                    "items": {
                      "$ref": "#/$defs/field_name"
                    }
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "kind",
                  "field"
                ],
                "properties": {
                  "kind": {
                    "const": "drop_required"
                  },
                  "field": {
                    "$ref": "#/$defs/field_name"
                  }
                }
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "kind",
                  "key",
                  "value"
                ],
                "properties": {
                  "kind": {
                    "const": "extra_key"
                  },
                  "key": {
                    "$ref": "#/$defs/field_name"
                  },
                  "value": {
                    "$ref": "#/$defs/scalar"
                  }
                }
              }
            ]
          }
        }
      }
    },
    "refusal_phrases": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/nonempty_string"
      }
    },
    "grounding": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "mode",
        "span_suffix",
        "span_fields",
        "value_in_span_fields",
        "abstain_fields"
      ],
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "none",
            "spans"
          ]
        },
        "span_suffix": {
          "type": "string",
          "pattern": "^_[a-z][a-z0-9_]{0,31}$"
        },
        "span_fields": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "value_in_span_fields": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "abstain_fields": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/field_name"
          }
        },
        "span_relaxations": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "enum": [
              "case_insensitive",
              "date_range_completion"
            ]
          },
          "description": "Relaxations of the verbatim span match; absent means verbatim. Written only when non-empty."
        }
      }
    },
    "repeats": {
      "type": "integer",
      "minimum": 0,
      "maximum": 10,
      "description": "How many times each baseline request is sent again as a REPEAT variant, to measure the endpoint's own noise floor. 0 switches the family off; larger models that reproduce their output need none."
    },
    "cycles": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "count"
      ],
      "properties": {
        "count": {
          "type": "integer",
          "minimum": 0,
          "maximum": 5,
          "description": "How many further cycles follow each baseline: the model is shown its previous answer and asked to check and correct it. 0 (and an absent cycles object) switches the CYCLE family off and leaves every plan unchanged."
        },
        "criticism": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "enum": [
              "none",
              "external"
            ]
          },
          "description": "What each cycle is shown beside the previous answer: none (self-revision) or external (the failed schema and grounding checks of the previous answer). The answer key is never fed back."
        }
      },
      "description": "Optional CYCLE family configuration; absent means off."
    },
    "unit_dependence": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "levels",
        "term_patterns"
      ],
      "properties": {
        "levels": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "integer",
            "minimum": 1,
            "maximum": 6
          },
          "description": "Markdown heading levels at which the case document is split into units, each removed in turn by the UNIT_DEPENDENCE family. An absent object switches the family off and leaves every plan unchanged."
        },
        "term_patterns": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          },
          "description": "Regular expressions whose matches (the capture group when there is one) are the document's terms; a unit is taken to define a term by first occurrence, heading, or an iff display, and a unit that defines a term the claim's own argument uses is related to the claim as declared."
        },
        "min_occurrences": {
          "type": "integer",
          "minimum": 1,
          "description": "A term counts only when the document uses it at least this many times; default 1."
        }
      }
    }

  },
  "$defs": {
    "nonempty_string": {
      "type": "string",
      "minLength": 1,
      "pattern": ".*\\S.*"
    },
    "identifier": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
    },
    "sentence_id": {
      "type": "string",
      "pattern": "^S[1-9][0-9]{0,3}$"
    },
    "field_name": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]{0,63}$"
    },
    "model_id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}$"
    },
    "relative_path": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._/-]{0,255}$"
    },
    "scalar": {
      "type": [
        "string",
        "boolean",
        "integer",
        "null"
      ]
    },
    "endpoint": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind",
        "base_url",
        "timeout_seconds",
        "options",
        "think"
      ],
      "properties": {
        "kind": {
          "const": "ollama-chat"
        },
        "base_url": {
          "type": "string",
          "pattern": "^https?://[^\\s/]+(/[^\\s]*)?$"
        },
        "timeout_seconds": {
          "type": "integer",
          "minimum": 1,
          "maximum": 3600
        },
        "options": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "temperature",
            "seed"
          ],
          "properties": {
            "temperature": {
              "type": "integer",
              "minimum": 0,
              "maximum": 2
            },
            "seed": {
              "type": "integer",
              "minimum": 0
            }
          }
        },
        "think": {
          "anyOf": [
            {
              "type": [
                "boolean",
                "null"
              ]
            },
            {
              "enum": [
                "low",
                "medium",
                "high"
              ]
            }
          ],
          "description": "The reasoning setting sent with every request: a boolean, or a level for the models that take one (gpt-oss ignores a boolean, L10). A run record carries the setting actually sent, which a run-time override may have changed from the pilot's."
        },
        "auth": {
          "description": "bearer: Authorization from OLLAMA_API_KEY (default when absent); none: no key, for a local Ollama.",
          "enum": [
            "bearer",
            "none"
          ]
        }
      }
    }
  }
}

