        }


@dataclass(frozen=True)
class PilotConfig:
    path: Path
    directory: Path
    spec: TaskSpec
    corpus_path: Path


def parse_instructions(source: str) -> tuple[str, tuple[str, ...]]:
    """Split instructions into a preamble and consecutively numbered sentences.

    The file must round-trip through :func:`render_instructions` so that the
    baseline variant's instruction text is byte-identical to the bound file.
    """

    lines = source.split("\n")
    preamble_lines: list[str] = []
    sentences: list[str] = []
    seen_numbered = False
    for line in lines:
        match = _NUMBERED_LINE.match(line)
        if match is None:
            if seen_numbered:
                if line == "":
                    continue
                raise RecordError(
                    "instructions must not contain unnumbered text after the first "
                    f"numbered sentence: {line!r}"
                )
            preamble_lines.append(line)
            continue
        seen_numbered = True
        number = int(match.group(1))
        if number != len(sentences) + 1:
            raise RecordError(
                f"instruction sentences must be numbered consecutively; found {number}"
            )
        sentences.append(match.group(2).rstrip())
    if not sentences:
        raise RecordError("instructions must contain at least one numbered sentence")
    preamble = "\n".join(preamble_lines).strip("\n")
    rendered = render_instructions(preamble, tuple(sentences))
    if rendered != source:
        raise RecordError(
            "instructions.md must be in canonical form: optional preamble, one blank "
            "line, consecutively numbered sentences, one trailing newline"
        )
    return preamble, tuple(sentences)


def render_instructions(preamble: str, sentences: tuple[str, ...]) -> str:
    body = "\n".join(f"{index}. {sentence}" for index, sentence in enumerate(sentences, start=1))
    if preamble:
        return preamble + "\n\n" + body + "\n"
    return body + "\n"


def mentioned_fields(sentence: str, fields: tuple[str, ...]) -> tuple[str, ...]:
    """Fields whose name appears in the sentence as a whole token, in text order."""

    positions: list[tuple[int, str]] = []
    for field in fields:
        match = re.search(r"(?<![A-Za-z0-9_])" + re.escape(field) + r"(?![A-Za-z0-9_])", sentence)
        if match is not None:
            positions.append((match.start(), field))
    return tuple(field for _, field in sorted(positions))


def validate_form_schema(raw: Any, where: str) -> tuple[dict[str, Any], tuple[str, ...]]:
    """Check the form schema is a valid, closed Draft 2020-12 object schema."""

    schema = object_value(raw, where)
    try:
        Draft202012Validator.check_schema(schema)
    except SchemaError as exc:
        raise RecordError(f"{where} is not a valid JSON Schema: {exc.message}") from exc
    errors = schema_errors(form_schema_profile_validator(), schema)
    if errors:
        raise RecordError(f"{where} violates the pilot form profile: " + "; ".join(errors[:5]))
    properties = object_value(schema.get("properties"), f"{where}.properties")
    field_order = tuple(field_name(key, f"{where}.properties key") for key in properties)
    required = array_value(schema.get("required"), f"{where}.required")
    for item in required:
        if item not in properties:
            raise RecordError(f"{where}.required names unknown field {item!r}")
    return schema, field_order


def endpoint_from_dict(raw: dict[str, Any]) -> Endpoint:
    raw = object_value(raw, "endpoint")
    options = object_value(raw["options"], "endpoint.options")
    if raw["kind"] != ENDPOINT_KIND:
        raise RecordError("endpoint.kind must be ollama-chat")
    # ``auth`` is optional so that records written before it existed still load; absent means bearer.
    auth = "bearer" if "auth" not in raw else text(raw["auth"], "endpoint.auth")
    if auth not in ENDPOINT_AUTH_MODES:
        raise RecordError(f"endpoint.auth must be one of {list(ENDPOINT_AUTH_MODES)}")
    return Endpoint(
        kind=ENDPOINT_KIND,
        base_url=text(raw["base_url"], "endpoint.base_url").rstrip("/"),
        timeout_seconds=integer(raw["timeout_seconds"], "endpoint.timeout_seconds", minimum=1),
        temperature=integer(options["temperature"], "endpoint.options.temperature"),
        seed=integer(options["seed"], "endpoint.options.seed"),
        think=think_setting(raw["think"], "endpoint.think"),
        auth=auth,
    )


def _charter(raw: dict[str, Any]) -> Charter:
    return Charter(
        purpose=text(raw["purpose"], "charter.purpose"),
        output=text(raw["output"], "charter.output"),
        scope_in=unique_texts(raw["scope_in"], "charter.scope_in"),
        scope_out=unique_texts(raw["scope_out"], "charter.scope_out"),
    )


def _controls(raw: list[Any], field_order: tuple[str, ...], required: tuple[str, ...]) -> tuple[Control, ...]:
    controls: list[Control] = []
    for index, item in enumerate(raw):
        where = f"controls[{index}]"
        entry = object_value(item, where)
        corruption = object_value(entry["corruption"], f"{where}.corruption")
        kind = text(corruption["kind"], f"{where}.corruption.kind")
        if kind not in CORRUPTION_KINDS:
            raise RecordError(f"{where}.corruption.kind is not a known corruption")
        fields: tuple[str, ...] = ()
        field: str | None = None
        key: str | None = None
        value: str | bool | int | None = None
        if kind == "swap_fields":
            fields = tuple(field_name(f, f"{where}.corruption.fields") for f in corruption["fields"])
            for f in fields:
                if f not in field_order:
                    raise RecordError(f"{where} swaps unknown field {f!r}")
        elif kind == "drop_required":
            field = field_name(corruption["field"], f"{where}.corruption.field")
            if field not in required:
                raise RecordError(f"{where} drops {field!r}, which is not a required field")
        elif kind == "extra_key":
            key = field_name(corruption["key"], f"{where}.corruption.key")
            if key in field_order:
                raise RecordError(f"{where} extra key {key!r} is already a form field")
            value = scalar(corruption["value"], f"{where}.corruption.value")
        controls.append(
            Control(
                control_id=identifier(entry["control_id"], f"{where}.control_id"),
                kind=kind,
                fields=fields,
                field=field,
                key=key,
                value=value,
            )
        )
    ids = [control.control_id for control in controls]
    if len(ids) != len(set(ids)):
        raise RecordError("controls must have unique control_id values")
    if not any(control.kind == "none" for control in controls):
        raise RecordError("controls must include one uncorrupted reference (kind none)")
    if not any(control.kind != "none" for control in controls):
        raise RecordError("controls must include at least one corruption")
    return tuple(controls)


def build_task_spec(
    *,
    raw_config: dict[str, Any],
    form_schema_raw: Any,
    instructions_text: str,
    bindings: tuple[Binding, ...],
) -> TaskSpec:
    """Derive the task specification from already-loaded, already-bound inputs."""

    validate_instance(raw_config, CONFIG_SCHEMA_NAME)
    if raw_config["schema_version"] != CONFIG_SCHEMA_VERSION:
        raise RecordError("pilot config schema_version mismatch")
    form_schema, field_order = validate_form_schema(form_schema_raw, "form_schema")
    required = tuple(field for field in field_order if field in form_schema["required"])
    preamble, sentence_texts = parse_instructions(instructions_text)
    sentences: list[Sentence] = []
    for index, sentence_text in enumerate(sentence_texts, start=1):
        mentions = mentioned_fields(sentence_text, field_order)
        sentences.append(
            Sentence(
                sentence_id=f"S{index}",
                text=sentence_text,
                mentions=mentions,
                primary_field=mentions[0] if mentions else None,
            )
        )
    sentence_ids = {sentence.sentence_id for sentence in sentences}

    ambiguities: list[Ambiguity] = []
    for index, item in enumerate(array_value(raw_config["ambiguity"], "ambiguity")):
        where = f"ambiguity[{index}]"
        entry = object_value(item, where)
        field = field_name(entry["field"], f"{where}.field")
        if field not in field_order:
            raise RecordError(f"{where} names unknown field {field!r}")
        rivals = tuple(
            RivalRule(
                label=identifier(rival["label"], f"{where}.rivals[{rival_index}].label"),
                instruction=text(rival["instruction"], f"{where}.rivals[{rival_index}].instruction"),
            )
            for rival_index, rival in enumerate(array_value(entry["rivals"], f"{where}.rivals"))
        )
        labels = [rival.label for rival in rivals]
        if len(labels) != len(set(labels)):
            raise RecordError(f"{where} rival labels must be unique")
        if len({rival.instruction for rival in rivals}) != len(rivals):
            raise RecordError(f"{where} rival instructions must differ")
        ambiguities.append(Ambiguity(field=field, question=text(entry["question"], f"{where}.question"), rivals=rivals))
    ambiguity_fields = [ambiguity.field for ambiguity in ambiguities]
    if len(ambiguity_fields) != len(set(ambiguity_fields)):
        raise RecordError("ambiguity declares the same field twice")
    ambiguity_by_field = {ambiguity.field: ambiguity for ambiguity in ambiguities}

    obligations: list[Obligation] = []
    for field in field_order:
        property_schema = object_value(form_schema["properties"][field], f"form_schema.properties.{field}")
        constraint = {key: property_schema[key] for key in _CONSTRAINT_KEYS if key in property_schema}
        sources = tuple(sentence for sentence in sentences if field in sentence.mentions)
        obligations.append(
            Obligation(
                field=field,
                json_type=text(property_schema["type"], f"form_schema.properties.{field}.type"),
                required=field in required,
                constraint=constraint or None,
                source_claim=sources[0].text if sources else None,
                source_sentence_ids=tuple(sentence.sentence_id for sentence in sources),
                unsourced=not sources,
                ambiguity=ambiguity_by_field.get(field),
            )
        )

    load_bearing = tuple(
        sentence_id(item, f"load_bearing[{index}]")
        for index, item in enumerate(array_value(raw_config["load_bearing"], "load_bearing"))
    )
    for item in load_bearing:
        if item not in sentence_ids:
            raise RecordError(f"load_bearing names unknown sentence {item!r}")
    if len(load_bearing) != len(set(load_bearing)):
        raise RecordError("load_bearing must not repeat a sentence")

    negations: list[Negation] = []
    for index, item in enumerate(array_value(raw_config["negations"], "negations")):
        where = f"negations[{index}]"
        entry = object_value(item, where)
        field = field_name(entry["field"], f"{where}.field")
        if field not in field_order:
            raise RecordError(f"{where} names unknown field {field!r}")
        target = sentence_id(entry["sentence_id"], f"{where}.sentence_id")
        if target not in sentence_ids:
            raise RecordError(f"{where} names unknown sentence {target!r}")
        primary = next(sentence for sentence in sentences if sentence.sentence_id == target).primary_field
        if primary != field:
            raise RecordError(f"{where} sentence {target} is not primarily about {field!r}")
        transform = text(entry["value_transform"], f"{where}.value_transform")
        if transform not in VALUE_TRANSFORMS:
            raise RecordError(f"{where}.value_transform is not a known transform")
        replacement_pattern = text(entry["replacement_pattern"], f"{where}.replacement_pattern")
        try:
            re.compile(replacement_pattern)
        except re.error as exc:
            raise RecordError(f"{where}.replacement_pattern is not a valid regex: {exc}") from exc
        negations.append(
            Negation(
                field=field,
                sentence_id=target,
                replacement_sentence=text(entry["replacement_sentence"], f"{where}.replacement_sentence"),
                replacement_pattern=replacement_pattern,
                value_transform=transform,
            )
        )
    negation_fields = [negation.field for negation in negations]
    if len(negation_fields) != len(set(negation_fields)):
        raise RecordError("negations declare the same field twice")

    twins: list[tuple[str, str]] = []
    for index, item in enumerate(array_value(raw_config["twins"], "twins")):
        where = f"twins[{index}]"
        pair = array_value(item, where)
        if len(pair) != 2:
            raise RecordError(f"{where} must name exactly two fields")
        first = field_name(pair[0], f"{where}[0]")
        second = field_name(pair[1], f"{where}[1]")
        if first == second:
            raise RecordError(f"{where} must name two different fields")
        for field in (first, second):
            if field not in field_order:
                raise RecordError(f"{where} names unknown field {field!r}")
            if not any(sentence.primary_field == field for sentence in sentences):
                raise RecordError(f"{where} field {field!r} has no primary instruction sentence")
        twins.append((first, second))

    controls = _controls(array_value(raw_config["controls"], "controls"), field_order, required)
    grounding = grounding_from_dict(raw_config["grounding"], field_order)
    repeats = integer(raw_config["repeats"], "repeats", minimum=0)
    if repeats > MAX_REPEATS:
        raise RecordError(f"repeats must be at most {MAX_REPEATS}")
    cycles = cycles_from_dict(raw_config.get("cycles"))
    unit_dependence = unit_dependence_from_dict(raw_config.get("unit_dependence"))
    refusal_phrases = unique_texts(raw_config["refusal_phrases"], "refusal_phrases")
    models = tuple(model_id(item, f"models[{index}]") for index, item in enumerate(raw_config["models"]))
    if len(models) != len(set(models)):
        raise RecordError("models must be unique")

    return TaskSpec(
        pilot_id=identifier(raw_config["pilot_id"], "pilot_id"),
        title=text(raw_config["title"], "title"),
        form_schema=form_schema,
        field_order=field_order,
        instructions=instructions_text,
        preamble=preamble,
        sentences=tuple(sentences),
        obligations=tuple(obligations),
        models=models,
        endpoint=endpoint_from_dict(object_value(raw_config["endpoint"], "endpoint")),
        charter=_charter(object_value(raw_config["charter"], "charter")),
        source_bindings=bindings,
        load_bearing=load_bearing,
        negations=tuple(negations),
        twins=tuple(twins),
        ambiguities=tuple(ambiguities),
        controls=controls,
        refusal_phrases=refusal_phrases,
        grounding=grounding,
        repeats=repeats,
        cycles=cycles,
        unit_dependence=unit_dependence,
    )


def load_pilot_config(path: Path) -> PilotConfig:
    """Strict-load ``pilot.json``, bind every referenced file, and build the spec."""

    if not isinstance(path, Path):
        raise TypeError("path must be pathlib.Path")
    directory = path.resolve().parent
    config_relative, config_sha256, config_raw = file_binding(path.resolve(), directory)
    raw_config = object_value(loads_strict(decode_utf8(config_raw, str(path))), "pilot config")
    validate_instance(raw_config, CONFIG_SCHEMA_NAME)
    bindings: list[Binding] = [Binding(config_relative, config_sha256)]

    def bound(key: str) -> tuple[Path, bytes]:
        relative = text(raw_config[key], key)
        target = (directory / relative).resolve()
        rel, sha256, raw = file_binding(target, directory)
        bindings.append(Binding(rel, sha256))
        return target, raw

    form_path, form_raw = bound("form_schema")
    form_schema_raw = loads_strict(decode_utf8(form_raw, str(form_path)))
    instructions_path, instructions_raw = bound("instructions")
    instructions_text = decode_utf8(instructions_raw, str(instructions_path))
    corpus_path, _ = bound("corpus")
    spec = build_task_spec(
        raw_config=raw_config,
        form_schema_raw=form_schema_raw,
        instructions_text=instructions_text,
        bindings=tuple(bindings),
    )
    return PilotConfig(path=path, directory=directory, spec=spec, corpus_path=corpus_path)

files.src/creib/forge/conformance/units.py:
"""Document units and the terms they define: the mechanical side of the UNIT_DEPENDENCE family.

A document under test is split into units at its own headings, with no manifest: every
heading at a configured level starts a unit that runs to the next heading at that level or
above. A unit is removed by deleting its lines and leaving every other line as it was.

Terms are whatever the configured patterns match in the document (a commitment name, a
symbol in a display, an abbreviation). A unit is taken to define a term when the term's
first occurrence is in it, when its heading names the term, or when it contains a display
that introduces the term with ``\\iff``. That is a heuristic over the document's own
conventions, not a reading of it; the family records what it computed, and the summary
compares it with what the model asserted and with what removal moved.

For one probe (a case whose preamble names the claim), each unit stands in one relation:
``self`` when its heading occurs in the preamble (the document's own argument for the
claim), ``declared`` when it defines a term the self units or the preamble use, and
``other`` otherwise. Nothing here calls a model or reads a key.
"""

from __future__ import annotations

from dataclasses import dataclass
import re
from typing import Iterable, Mapping

from creib.errors import RecordError

from .common import array_value, integer, object_value, text

_HEADING = re.compile(r"^(#{1,6})[ \t]+(.+?)[ \t]*$")
_FENCE = re.compile(r"^\s*(```|~~~)")
_DISPLAY_OPEN = re.compile(r"^\s*\\\[\s*$")
_DISPLAY_CLOSE = re.compile(r"^\s*\\\]\s*$")
UNIT_RELATIONS: tuple[str, ...] = ("self", "declared", "other")
MAX_HEADING_LEVEL = 6


@dataclass(frozen=True)
class Unit:
    unit_id: str
    level: int
    title: str
    start: int
    end: int

    def to_dict(self) -> dict[str, object]:
        return {"unit_id": self.unit_id, "level": self.level, "title": self.title, "start": self.start, "end": self.end}


@dataclass(frozen=True)
class UnitDependence:
    """Configuration of the UNIT_DEPENDENCE family; empty ``levels`` (the default) switches it off."""

    levels: tuple[int, ...]
    term_patterns: tuple[str, ...]
    min_occurrences: int

    @property
    def active(self) -> bool:
        return bool(self.levels)

    def to_dict(self) -> dict[str, object]:
        return {"levels": list(self.levels), "term_patterns": list(self.term_patterns), "min_occurrences": self.min_occurrences}


def unit_dependence_from_dict(raw: object, where: str = "unit_dependence") -> UnitDependence:
    if raw is None:
        return UnitDependence(levels=(), term_patterns=(), min_occurrences=1)
    record = object_value(raw, where)
    levels: list[int] = []
    for index, item in enumerate(array_value(record["levels"], f"{where}.levels")):
        level = integer(item, f"{where}.levels[{index}]", minimum=1)
        if level > MAX_HEADING_LEVEL:
            raise RecordError(f"{where}.levels[{index}] must be at most {MAX_HEADING_LEVEL}")
        if level in levels:
            raise RecordError(f"{where}.levels repeats {level}")
        levels.append(level)
    if not levels:
        raise RecordError(f"{where}.levels must name at least one heading level")
    patterns: list[str] = []
    for index, item in enumerate(array_value(record["term_patterns"], f"{where}.term_patterns")):
        pattern = text(item, f"{where}.term_patterns[{index}]")
        try:
            compiled = re.compile(pattern)
        except re.error as exc:
            raise RecordError(f"{where}.term_patterns[{index}] is not a valid regular expression: {exc}") from exc
        if compiled.groups > 1:
            raise RecordError(f"{where}.term_patterns[{index}] must have at most one capture group")
        if pattern in patterns:
            raise RecordError(f"{where}.term_patterns repeats {pattern!r}")
        patterns.append(pattern)
    if not patterns:
        raise RecordError(f"{where}.term_patterns must name at least one pattern")
    minimum = integer(record.get("min_occurrences", 1), f"{where}.min_occurrences", minimum=1)
    return UnitDependence(levels=tuple(levels), term_patterns=tuple(patterns), min_occurrences=minimum)


def _headings(lines: list[str]) -> list[tuple[int, int, str]]:
    """(line index, level, title) for every heading outside a fenced code block."""

    found: list[tuple[int, int, str]] = []
    fenced = False
    for index, line in enumerate(lines):
        if _FENCE.match(line):
            fenced = not fenced
            continue
        if fenced:
            continue
        match = _HEADING.match(line)
        if match is not None:
            found.append((index, len(match.group(1)), match.group(2)))
    return found


def split_units(document: str, levels: tuple[int, ...]) -> tuple[Unit, ...]:
    """The units of a document at the given heading levels, in document order.

    A unit runs from its heading line to the line before the next heading whose level is at
    or above the deepest configured level; headings above every configured level (a part
    title) end a unit and belong to none, so they are never removed.
    """

    if not levels:
        raise RecordError("split_units needs at least one heading level")
    lines = document.split("\n")
    headings = _headings(lines)
    deepest = max(levels)
    units: list[Unit] = []
    for position, (start, level, title) in enumerate(headings):
        if level not in levels:
            continue
        end = len(lines)
        for later_start, later_level, _ in headings[position + 1:]:
            if later_level <= deepest:
                end = later_start
                break
        units.append(Unit(unit_id=f"U{len(units) + 1:02d}", level=level, title=title, start=start, end=end))
    return tuple(units)


def preamble_text(document: str) -> str:
    """The lines before the first heading; the part of a case document that a unit removal never touches."""

    lines = document.split("\n")
    headings = _headings(lines)
    if not headings:
        return document
    return "\n".join(lines[: headings[0][0]])


def unit_text(document: str, unit: Unit) -> str:
    return "\n".join(document.split("\n")[unit.start : unit.end])


def remove_unit(document: str, unit: Unit) -> str:
    """The document with the unit's lines deleted and every other line byte-identical."""

    lines = document.split("\n")
    if unit.start < 0 or unit.end > len(lines) or unit.start >= unit.end:
        raise RecordError(f"unit {unit.unit_id} does not lie inside the document")
    return "\n".join(lines[: unit.start] + lines[unit.end :])


def _term_spans(text_value: str, patterns: Iterable[str]) -> dict[tuple[int, int], str]:
    """Every span a pattern matches, keyed by the span of the term itself (the capture group when there is one).

    Two patterns that match the same characters (a symbol inside a display and the bare
    abbreviation) count as one occurrence, not two.
    """

    spans: dict[tuple[int, int], str] = {}
    for pattern in patterns:
        compiled = re.compile(pattern)
        for match in compiled.finditer(text_value):
            group = 1 if compiled.groups else 0
            spans[match.span(group)] = match.group(group)
    return spans


def terms_in(text_value: str, patterns: Iterable[str]) -> tuple[str, ...]:
    """Every term a pattern matches in the text, sorted and unique; the capture group when the pattern has one."""

    return tuple(sorted(set(_term_spans(text_value, patterns).values())))


def term_occurrences(document: str, patterns: Iterable[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for term in _term_spans(document, patterns).values():
        counts[term] = counts.get(term, 0) + 1
    return counts


def document_terms(document: str, config: UnitDependence) -> tuple[str, ...]:
    """The terms the document uses at least ``min_occurrences`` times, sorted."""

    counts = term_occurrences(document, config.term_patterns)
    return tuple(sorted(term for term, count in counts.items() if count >= config.min_occurrences))


def _display_blocks(lines: list[str]) -> list[tuple[int, int]]:
    blocks: list[tuple[int, int]] = []
    open_at: int | None = None
    for index, line in enumerate(lines):
        if open_at is None and _DISPLAY_OPEN.match(line):
            open_at = index
        elif open_at is not None and _DISPLAY_CLOSE.match(line):
            blocks.append((open_at, index + 1))
            open_at = None
    return blocks


def defining_units(document: str, units: tuple[Unit, ...], config: UnitDependence) -> dict[str, tuple[str, ...]]:
    """term -> the unit ids taken to define it (first occurrence, heading, or an ``\\iff`` display)."""

    lines = document.split("\n")
    terms = document_terms(document, config)
    result: dict[str, list[str]] = {term: [] for term in terms}
    if not terms:
        return {}
    for term in terms:
        first_line: int | None = None
        for index, line in enumerate(lines):
            if term in terms_in(line, config.term_patterns):
                first_line = index
                break
        for unit in units:
            defines = False
            if first_line is not None and unit.start <= first_line < unit.end:
                defines = True
            if term in terms_in(unit.title, config.term_patterns):
                defines = True
            if not defines:
                for open_at, close_at in _display_blocks(lines):
                    if open_at < unit.start or close_at > unit.end:
                        continue
                    block = "\n".join(lines[open_at:close_at])
                    if "\\iff" in block and term in terms_in(block, config.term_patterns):
                        defines = True
                        break
            if defines and unit.unit_id not in result[term]:
                result[term].append(unit.unit_id)
    return {term: tuple(ids) for term, ids in result.items()}


@dataclass(frozen=True)
class UnitRelation:
    unit: Unit
    relation: str
    defines: tuple[str, ...]


def relate_units(document: str, config: UnitDependence) -> tuple[UnitRelation, ...]:
    """Each unit of a case document with its relation to the claim the preamble names.

    ``self``: the unit's heading occurs in the preamble. ``declared``: the unit defines a term
    that a self unit or the preamble uses. ``other``: neither. Every unit also carries the
    terms it is taken to define, so a record says what the classification rested on.
    """

    if not config.active:
        raise RecordError("relate_units needs an active unit_dependence configuration")
    units = split_units(document, config.levels)
    if not units:
        raise RecordError(f"the document has no unit at heading levels {list(config.levels)}")
    preamble = preamble_text(document)
    defining = defining_units(document, units, config)
    self_ids = {unit.unit_id for unit in units if unit.title and unit.title in preamble}
    used: set[str] = set(terms_in(preamble, config.term_patterns))
    for unit in units:
        if unit.unit_id in self_ids:
            used.update(terms_in(unit_text(document, unit), config.term_patterns))
    declared_ids = {unit_id for term, ids in defining.items() if term in used for unit_id in ids} - self_ids
    defines_by_unit: dict[str, list[str]] = {unit.unit_id: [] for unit in units}
    for term, ids in defining.items():
        for unit_id in ids:
            defines_by_unit[unit_id].append(term)
    relations: list[UnitRelation] = []
    for unit in units:
        relation = "self" if unit.unit_id in self_ids else "declared" if unit.unit_id in declared_ids else "other"
        relations.append(UnitRelation(unit=unit, relation=relation, defines=tuple(sorted(defines_by_unit[unit.unit_id]))))
    return tuple(relations)


def unit_table_markdown(document: str, config: UnitDependence, relations: Mapping[str, tuple[UnitRelation, ...]] | None = None) -> str:
    """The document's units and the terms each is taken to define; model-free."""

    units = split_units(document, config.levels)
    defining = defining_units(document, units, config)
    defines_by_unit: dict[str, list[str]] = {unit.unit_id: [] for unit in units}
    for term, ids in defining.items():
        for unit_id in ids:
            defines_by_unit[unit_id].append(term)
    rows = ["| unit | level | title | lines | defines |", "|---|---|---|---|---|"]
    for unit in units:
        rows.append(f"| {unit.unit_id} | {unit.level} | {unit.title} | {unit.start + 1}-{unit.end} | {', '.join(sorted(defines_by_unit[unit.unit_id])) or '-'} |")
    parts = ["## Units", "", *rows, ""]
    undefined = [term for term, ids in defining.items() if not ids]
    if undefined:
        parts.append(f"Terms that no unit is taken to define: {', '.join(undefined)}.")
        parts.append("")
    if relations:
        parts.append("## Relations by probe")
        parts.append("")
        parts.append("| probe | self | declared | other |")
        parts.append("|---|---|---|---|")
        for probe_id, items in relations.items():
            by_relation = {name: [r.unit.unit_id for r in items if r.relation == name] for name in UNIT_RELATIONS}
            parts.append(f"| {probe_id} | {', '.join(by_relation['self']) or '-'} | {', '.join(by_relation['declared']) or '-'} | {len(by_relation['other'])} units |")
        parts.append("")
    return "\n".join(parts)


__all__ = [
    "MAX_HEADING_LEVEL",
    "UNIT_RELATIONS",
    "Unit",
    "UnitDependence",
    "UnitRelation",
    "defining_units",
    "document_terms",
    "preamble_text",
    "relate_units",
    "remove_unit",
    "split_units",
    "term_occurrences",
    "terms_in",
    "unit_dependence_from_dict",
    "unit_table_markdown",
    "unit_text",
]

files.src/creib/forge/mini/attention.py:
"""Attention: the plug, not the brain (R18, R20, R21).

An attention policy is a registered function that decides which stage runs
next. It is handed two things and nothing else: a view of the signals it
declared it reads, and the stages still to run. There is no parameter through
which the record could arrive, and registration refuses a function whose
signature would take one — that is what makes attention a decision of the
machine rather than of the operator, and what keeps a policy from reading round
the signal interface.

Two policies ship. ``mini.attention.off`` is the default and returns nothing at
all, so the declared order runs exactly as written. The other prefers, of the
stages still to run, the one whose kind has the most unanswered criticisms
about it; it reads a count keyed by kind id and knows no kind's name, so a kind
invented after it was written is visible to it.

This module imports nothing that touches the record. That is checked.
"""

from __future__ import annotations

import inspect
from dataclasses import dataclass
from typing import Any, Callable, Iterator, Mapping

from .common import MiniError

ATTENTION_OFF = "mini.attention.off"
ATTENTION_MOST_UNANSWERED = "mini.attention.most-unanswered-criticisms"
SIGNAL_UNANSWERED_BY_KIND = "mini.signal.unanswered-criticisms-by-kind"
_SIGNATURE: tuple[str, ...] = ("signals", "stages")


@dataclass(frozen=True)
class PendingStage:
    """One stage still to run, as an attention policy sees it."""

    stage_id: str
    kind_id: str


class SignalView(Mapping[str, Any]):
    """A read-only view of exactly the signals a policy declared.

    Asking for anything else is a typed refusal, not a missing key: a policy
    that reaches beyond what it declared stops the run rather than quietly
    reading nothing.
    """

    def __init__(self, values: Mapping[str, Any], declared: tuple[str, ...], policy_id: str) -> None:
        self._declared = tuple(declared)
        self._policy_id = policy_id
        self._values = {name: values[name] for name in self._declared if name in values}
        self.read: list[str] = []

    def __getitem__(self, key: str) -> Any:
        if key not in self._declared:
            raise MiniError(
                "MINI_ATTENTION_UNDECLARED_SIGNAL",
                f"attention policy {self._policy_id!r} asked for the signal {key!r}, which it does not declare",
            )
        self.read.append(key)
        return self._values.get(key, {})

    def __iter__(self) -> Iterator[str]:
        return iter(self._declared)

    def __len__(self) -> int:
        return len(self._declared)


@dataclass(frozen=True)
class AttentionPolicy:
    """One registered attention policy."""

    policy_id: str
    reads_signals: tuple[str, ...]
    description: str
    choose: Callable[[SignalView, tuple[PendingStage, ...]], str | None]


_REGISTRY: dict[str, AttentionPolicy] = {}


def register_attention_policy(policy: AttentionPolicy) -> AttentionPolicy:
    """Register one policy, refusing a function that could be handed a record."""

    if policy.policy_id in _REGISTRY:
        raise MiniError("MINI_ATTENTION_POLICY_DUPLICATE", f"attention policy {policy.policy_id!r} is already registered")
    parameters = tuple(inspect.signature(policy.choose).parameters)
    if parameters != _SIGNATURE:
        raise MiniError(
            "MINI_ATTENTION_SIGNATURE",
            f"attention policy {policy.policy_id!r} takes {list(parameters)}; it may take only {list(_SIGNATURE)}",
        )
    _REGISTRY[policy.policy_id] = policy
    return policy


def resolve_attention_policy(policy_id: str) -> AttentionPolicy:
    try:
        return _REGISTRY[policy_id]
    except KeyError as error:
        raise MiniError(
            "MINI_ATTENTION_POLICY_UNKNOWN",
            f"no attention policy {policy_id!r} is registered; known: {sorted(_REGISTRY)}",
        ) from error


def registered_attention_policies() -> tuple[AttentionPolicy, ...]:
    return tuple(_REGISTRY[name] for name in sorted(_REGISTRY))


def choose_next(
    policy: AttentionPolicy,
    signals: Mapping[str, Any],
    stages: tuple[PendingStage, ...],
) -> str | None:
    """Ask one policy for the next stage. ``None`` means follow the declared order."""

    view = SignalView(signals, policy.reads_signals, policy.policy_id)
    chosen = policy.choose(view, stages)
    if chosen is None:
        return None
    if chosen not in {stage.stage_id for stage in stages}:
        raise MiniError(
            "MINI_ATTENTION_STAGE_UNKNOWN",
            f"attention policy {policy.policy_id!r} chose {chosen!r}, which is not a stage still to run",
        )
    return chosen


def _off(signals: SignalView, stages: tuple[PendingStage, ...]) -> str | None:
    return None


def _most_unanswered(signals: SignalView, stages: tuple[PendingStage, ...]) -> str | None:
    counts = signals[SIGNAL_UNANSWERED_BY_KIND]
    best: str | None = None
    best_count = 0
    for stage in stages:
        count = int(counts.get(stage.kind_id, 0))
        if count > best_count:
            best, best_count = stage.stage_id, count
    return best


OFF_POLICY = register_attention_policy(
    AttentionPolicy(
        policy_id=ATTENTION_OFF,
        reads_signals=(),
        description="Follow the declared order exactly. The default.",
        choose=_off,
    )
)

MOST_UNANSWERED_POLICY = register_attention_policy(
    AttentionPolicy(
        policy_id=ATTENTION_MOST_UNANSWERED,
        reads_signals=(SIGNAL_UNANSWERED_BY_KIND,),
        description="Prefer the stage whose kind has the most unanswered criticisms about it.",
        choose=_most_unanswered,
    )
)

files.src/creib/forge/mini/buildtest.py:
"""BUILD-TEST-1: does a proposer that must reconstruct produce what one that may relay does not?

The protocol is ``docs/mini/BUILD_TEST.md``, pre-registered before any arm ran. This module is
its machinery and decides nothing: it asks, it executes, it records.

*Explanatory Construction Semantics 2.0* §6.3 defines an originative act as
``Origin ⟺ Attempt ∧ New ∧ Build``. ``New`` is unestablishable for a model whose repertoire
before the event cannot be inspected (§6.2, the incomplete-archive case), so nothing here can
establish ``Origin`` and nothing here claims to. ``Build`` — "a nontrivial binding construction,
not a composition of content-preserving transfers" — is what two arms are separated on, by
§6.2's own phrase: learner reconstruction counts, relay does not.

Arm **R** is shown the checks' documented rules and no code. Arm **L** is shown the rules and the
complete source. Everything else is identical, the grid of MINI-USE-TEST-1 is gone (§8.3
condition 3), and no defect is seeded: a contradiction here is a place where this repository's
documentation and its behaviour disagree.
"""

from __future__ import annotations

import json
import os
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path
from types import ModuleType
from typing import Any, Mapping, Sequence

from creib.errors import RecordError
from creib.strict_json import loads_strict

from .common import MiniError
from .usetest import KERNEL_IDS, load_subject, rules_text, run_kernel, subject_source

BUILD_TEST_ID = "build-test-1"

#: The method version. A change to a prompt, an arm, a measure or a path is a new version and a
#: new block, and blocks are never compared arm for arm across versions.
METHOD_VERSION = 1

ARM_RECONSTRUCT = "R"
ARM_RELAY = "L"
ARMS: tuple[str, ...] = (ARM_RECONSTRUCT, ARM_RELAY)

#: The checks a proposal may name. The three that read a whole reply; the grounding pair takes a
#: structured input and is not enumerable from a free-form text (MINI-USE-TEST-1's NON_ENUMERABLE).
OPEN_KERNELS: tuple[str, ...] = ("recovery", "recovered-from-prose", "response-verdict", "refusal-phrase")

PROPOSAL_FIELDS: tuple[str, ...] = ("kernel", "expect", "input", "rewritten", "reading")

PROPOSAL_SCHEMA: dict[str, Any] = {
    "type": "object",
    "required": list(PROPOSAL_FIELDS),
    "properties": {
        "kernel": {"type": "string", "enum": list(OPEN_KERNELS)},
        "expect": {"type": "string", "enum": ["moves", "unchanged"]},
        "input": {"type": "string"},
        "rewritten": {"type": "string"},
        "reading": {"type": "string"},
    },
}

_TASK = (
    "You are testing one check that reads a model's reply and reports what it found in it.\n\n"
    "Build TWO texts. \"input\" is any reply text you like. \"rewritten\" is a second text, "
    "different from the first — change it however you judge most informative. Then say what the "
    "RULE AS WRITTEN says the check's answer ought to do between the two texts: \"moves\" if the "
    "rule says the answer should differ, \"unchanged\" if the rule says it should stay the same.\n\n"
    "Your expectation must come from the rule's words. Quote the words you read it from in "
    "\"reading\", and name which answer the rule gives for each text.\n\n"
    "Choose the pair that would be most informative about whether the check does what its "
    "description says. A pair whose answer is obvious teaches nothing.\n\n"
    "Write real line breaks in the texts, never the two characters backslash and n. Return JSON "
    "only, one object with exactly these string fields: "
    + ", ".join(f'"{name}"' for name in PROPOSAL_FIELDS)
    + '. "kernel" is one of '
    + ", ".join(OPEN_KERNELS)
    + '. "expect" is "moves" or "unchanged". Write nothing outside the JSON object.'
)

_SHOWN_RULES = (
    "You are shown the checks' documented rules — every definition's signature and its "
    "description — and none of their code. "
)
_SHOWN_SOURCE = (
    "You are shown the checks' documented rules and their complete source. "
)


def brief(arm: str, source: str) -> tuple[str, str]:
    """The system prompt and the user text one arm is given. They differ in one clause and one section."""

    if arm not in ARMS:
        raise MiniError("MINI_BUILDTEST_ARM_UNKNOWN", f"{arm!r} is not an arm; those are {', '.join(ARMS)}")
    system = (_SHOWN_RULES if arm == ARM_RECONSTRUCT else _SHOWN_SOURCE) + _TASK
    user = "## The documented rules of the checks\n\n" + rules_text(source)
    if arm == ARM_RELAY:
        user += "\n\n## The source of the checks\n\n" + source
    return system, user


@dataclass(frozen=True)
class Proposal:
    """One reply, read into the shape the task asked for."""

    kernel: str
    expect: str
    input: str
    rewritten: str
    reading: str

    def to_dict(self) -> dict[str, str]:
        return {name: getattr(self, name) for name in PROPOSAL_FIELDS}


def unfence(reply: str) -> str:
    """A reply with one enclosing code fence removed, if it has one.

    A fence around a whole reply is a content-preserving wrapper (mini register M4): the object
    inside is unchanged, and the fields this protocol measures live inside that object. Refusing
    a fenced reply would score a model's formatting habit rather than its construction, which is
    a confound between the instrument and the thing measured, so the fence comes off and the
    record says it did. Nothing inside the object is touched.
    """

    text = reply.strip()
    if not text.startswith("```"):
        return reply
    body = text[3:]
    newline = body.find("\n")
    if newline == -1:
        return reply
    if body[:newline].strip() not in ("", "json", "JSON"):
        return reply
    body = body[newline + 1 :]
    closing = body.rfind("```")
    return body[:closing] if closing != -1 else body


def read_proposal(reply: str) -> tuple[Proposal | None, bool]:
    """A reply as a proposal and whether a fence had to come off, or nothing and why not."""

    unfenced = unfence(reply)
    fenced = unfenced != reply
    try:
        parsed = loads_strict(unfenced)
    except RecordError:
        try:
            parsed = loads_strict(unfenced, control_characters=True)
        except RecordError:
            return None, fenced
    if type(parsed) is not dict:
        return None, fenced
    values = {name: parsed.get(name) for name in PROPOSAL_FIELDS}
    if any(type(value) is not str for value in values.values()):
        return None, fenced
    if values["kernel"] not in OPEN_KERNELS or values["expect"] not in ("moves", "unchanged"):
        return None, fenced
    return Proposal(**values), fenced  # type: ignore[arg-type]


#: The one boundary this repository already knows about, as a predicate over a pair rather than a
#: string match: a fence holding a sentence beside its object, scored on a bare object after it.
def reproduces_h43(subject: ModuleType, text: str) -> bool:
    """Does this text exhibit H43 — a fence holding prose and an object, with a bare object after?"""

    if "```" not in text:
        return False
    head, _, tail = text.rpartition("```")
    if not tail.strip() or not tail.strip().startswith("{"):
        return False
    inside = head.split("```")
    if len(inside) < 2:
        return False
    fenced = inside[-1]
    has_prose = any(line.strip() and not line.strip().startswith(("{", "[")) for line in fenced.splitlines())
    has_object = "{" in fenced
    return bool(has_prose and has_object)


@dataclass
class Execution:
    """What the machine did with one proposal. Nothing here is a verdict."""

    proposal: Proposal
    executed: str
    before: str = ""
    after: str = ""
    detail: str = ""

    @property
    def contradicted(self) -> bool:
        if self.executed not in ("moved", "unchanged"):
            return False
        return (self.executed == "moved") != (self.proposal.expect == "moves")

    @property
    def behaviour(self) -> tuple[str, str, str]:
        return (self.proposal.kernel, self.before, self.after)

    def to_dict(self) -> dict[str, Any]:
        return {
            **self.proposal.to_dict(),
            "executed": self.executed,
            "before": self.before,
            "after": self.after,
            "detail": self.detail,
            "contradicted": self.contradicted,
        }


def execute(subject: ModuleType, proposal: Proposal) -> Execution:
    """Run the named check on both texts. A degenerate pair is recorded as such, never scored."""

    if proposal.input == proposal.rewritten:
        return Execution(proposal, "degenerate", detail="the two texts are the same text")
    if not proposal.input.strip() or not proposal.rewritten.strip():
        return Execution(proposal, "degenerate", detail="one of the texts is empty")
    try:
        before = run_kernel(subject, proposal.kernel, proposal.input)
        after = run_kernel(subject, proposal.kernel, proposal.rewritten)
    except MiniError as error:
        return Execution(proposal, "unrunnable", detail=str(error))
    return Execution(proposal, "moved" if before != after else "unchanged", before=before, after=after)


# --- the two paths a call may take, and the one place each key is read ---

#: Where the vendor key is read from, as a path to a file. The key is never a value in a manifest,
#: a record, a log or an exception; it is read at call time and nowhere else.
DEEPSEEK_KEY_FILE_ENV = "DEEPSEEK_KEY_FILE"
OLLAMA_KEY_ENV = "OLLAMA_API_KEY"

PATH_OLLAMA = "ollama.com"
PATH_DEEPSEEK = "api.deepseek.com"
PATHS: tuple[str, ...] = (PATH_OLLAMA, PATH_DEEPSEEK)


@dataclass(frozen=True)
class Endpoint:
    """What a call is sent to, and what the record says it was sent to.

    ``quantised`` is declared, not detected: ``api.deepseek.com`` serves the vendor's own weights
    and ``ollama.com`` may serve quantised ones, which makes one model on both paths a
    quantisation comparison at fixed prompt. Nothing here verifies the claim; it records which
    path was used so a reader can.
    """

    path: str
    model: str
    think: bool | str | None
    timeout_seconds: int = 900
    max_tokens: int | None = None

    @property
    def quantisation(self) -> str:
        return "vendor weights, unquantised" if self.path == PATH_DEEPSEEK else "unknown, may be quantised"

    def to_dict(self) -> dict[str, Any]:
        return {
            "path": self.path,
            "model": self.model,
            "think": self.think,
            "timeout_seconds": self.timeout_seconds,
            "max_tokens": self.max_tokens,
            "quantisation": self.quantisation,
        }


@dataclass
class Reply:
    """One call's outcome, whether or not it produced anything readable."""

    text: str
    completion_tokens: int
    prompt_tokens: int
    elapsed_s: int
    ok: bool
    detail: str = ""

    def to_dict(self) -> dict[str, Any]:
        return {
            "completion_tokens": self.completion_tokens,
            "prompt_tokens": self.prompt_tokens,
            "elapsed_s": self.elapsed_s,
            "ok": self.ok,
            "detail": self.detail,
        }


def _post(url: str, body: dict[str, Any], key: str, timeout: int) -> tuple[int, bytes]:
    request = urllib.request.Request(
        url,
        data=json.dumps(body).encode("utf-8"),
        method="POST",
        headers={"Content-Type": "application/json", "Authorization": "Bearer " + key},
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return int(response.status), response.read()
    except urllib.error.HTTPError as error:
        try:
            raw = error.read()
        except (OSError, ValueError):
            raw = b""
        return int(error.code), raw


def ask(endpoint: Endpoint, system: str, user: str) -> Reply:
    """One call on the declared path. The key is read here and appears in nothing this returns."""

    started = time.monotonic()
    if endpoint.path == PATH_OLLAMA:
        key = os.environ.get(OLLAMA_KEY_ENV, "")
        if not key:
            raise MiniError("MINI_BUILDTEST_KEY_MISSING", f"{OLLAMA_KEY_ENV} is not set, so no call can be made")
        options: dict[str, int] = {"temperature": 0, "seed": 7}
        if endpoint.max_tokens is not None:
            options["num_predict"] = endpoint.max_tokens
        body: dict[str, Any] = {
            "model": endpoint.model,
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
            "stream": False,
            "options": options,
            "format": PROPOSAL_SCHEMA,
        }
        if endpoint.think is not None:
            body["think"] = endpoint.think
        status, raw = _post("https://ollama.com/api/chat", body, key, endpoint.timeout_seconds)
    elif endpoint.path == PATH_DEEPSEEK:
        where = os.environ.get(DEEPSEEK_KEY_FILE_ENV, "")
        if not where or not Path(where).is_file():
            raise MiniError("MINI_BUILDTEST_KEY_MISSING", f"{DEEPSEEK_KEY_FILE_ENV} names no readable file")
        key = Path(where).read_text(encoding="utf-8").strip()
        body = {
            "model": endpoint.model,
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
            "temperature": 0,
            "response_format": {"type": "json_object"},
            "stream": False,
        }
        if endpoint.max_tokens is not None:
            body["max_tokens"] = endpoint.max_tokens
        status, raw = _post("https://api.deepseek.com/chat/completions", body, key, endpoint.timeout_seconds)
    else:
        raise MiniError("MINI_BUILDTEST_PATH_UNKNOWN", f"{endpoint.path!r} is not a path; those are {', '.join(PATHS)}")

    elapsed = int(time.monotonic() - started)
    redacted = raw.decode("utf-8", errors="replace").replace(key, "<redacted>")
    if status != 200:
        return Reply("", 0, 0, elapsed, False, f"HTTP {status}: {redacted[:300]}")
    try:
        parsed = json.loads(redacted)
    except ValueError as error:
        return Reply("", 0, 0, elapsed, False, f"the body is not JSON: {error}")
    if endpoint.path == PATH_OLLAMA:
        message = parsed.get("message") or {}
        text = str(message.get("content") or "")
        return Reply(text, int(parsed.get("eval_count") or 0), int(parsed.get("prompt_eval_count") or 0),
                     elapsed, bool(text.strip()), "" if text.strip() else "the reply carried no content")
    choice = (parsed.get("choices") or [{}])[0]
    text = str(((choice.get("message") or {}).get("content")) or "")
    usage = parsed.get("usage") or {}
    return Reply(text, int(usage.get("completion_tokens") or 0), int(usage.get("prompt_tokens") or 0),
                 elapsed, bool(text.strip()), "" if text.strip() else "the reply carried no content")


# --- a condition, its run, and the measures the protocol fixed before any of it ran ---


@dataclass(frozen=True)
class Condition:
    """One cell of the design: an arm, an endpoint, and how many proposals to ask for."""

    arm: str
    endpoint: Endpoint
    proposals: int = 10
    grid_cells: tuple[str, ...] = ()

    @property
    def condition_id(self) -> str:
        grid = "grid" if self.grid_cells else "nogrid"
        think = {True: "think-on", False: "think-off", None: "think-default"}.get(self.endpoint.think, str(self.endpoint.think))
        return f"{self.endpoint.path}/{self.endpoint.model}/arm-{self.arm}/{think}/{grid}"

    def to_dict(self) -> dict[str, Any]:
        return {
            "condition_id": self.condition_id,
            "arm": self.arm,
            "endpoint": self.endpoint.to_dict(),
            "proposals_requested": self.proposals,
            "grid_cells": list(self.grid_cells),
        }


def run_condition(condition: Condition, subject: ModuleType, source: str) -> dict[str, Any]:
    """Ask, execute, record. Each proposal is one call; nothing is retried and nothing is repaired."""

    system, user = brief(condition.arm, source)
    executions: list[Execution] = []
    calls: list[dict[str, Any]] = []
    seen: list[str] = []
    for index in range(condition.proposals):
        shown = user
        if condition.grid_cells:
            shown += "\n\n## The shape to build\n\n" + condition.grid_cells[index % len(condition.grid_cells)]
        if seen:
            # A proposer that repeats itself measures nothing twice (mini register M10), so the
            # pairs already built are shown back. This is the run's own history, never a hint.
            shown += "\n\n## Pairs you have already built, which you may not repeat\n\n" + "\n\n".join(seen[-8:])
        reply = ask(condition.endpoint, system, shown)
        calls.append({"index": index, **reply.to_dict()})
        if not reply.ok:
            continue
        proposal, fenced = read_proposal(reply.text)
        calls[-1]["fenced"] = fenced
        if proposal is None:
            # A refused reply is kept verbatim, as mini's own H1 requires: the record has to say
            # what the model actually returned, not only that it was turned away.
            calls[-1]["detail"] = calls[-1]["detail"] or "the reply could not be read as a proposal"
            calls[-1]["refused_reply"] = reply.text[:8000]
            continue
        seen.append(f"{proposal.kernel}: {proposal.input[:160]!r} -> {proposal.rewritten[:160]!r}")
        executions.append(execute(subject, proposal))
    return {
        "condition": condition.to_dict(),
        "method_version": METHOD_VERSION,
        "calls": calls,
        "executions": [item.to_dict() for item in executions],
        "measures": measures(executions, subject),
    }


def measures(executions: Sequence[Execution], subject: ModuleType) -> dict[str, Any]:
    """The six measures the protocol fixed. None is a score and no arm is ranked by them."""

    ran = [item for item in executions if item.executed in ("moved", "unchanged")]
    contradicted = [item for item in ran if item.contradicted]
    behaviours = sorted({item.behaviour for item in ran})
    return {
        "proposals": len(executions),
        "executed": len(ran),
        "degenerate": sum(1 for item in executions if item.executed == "degenerate"),
        "unrunnable": sum(1 for item in executions if item.executed == "unrunnable"),
        "contradicted": len(contradicted),
        "distinct_behaviours": len(behaviours),
        "behaviours": [list(item) for item in behaviours],
        "reproduces_h43": sum(1 for item in contradicted if reproduces_h43(subject, item.proposal.input)),
        "contradictions": [item.to_dict() for item in contradicted],
    }


def unique_to_arm(this: Mapping[str, Any], other: Mapping[str, Any]) -> list[list[str]]:
    """Behaviour triples this condition produced that the other did not. §6.2's measure."""

    mine = {tuple(item) for item in this["measures"]["behaviours"]}
    theirs = {tuple(item) for item in other["measures"]["behaviours"]}
    return [list(item) for item in sorted(mine - theirs)]

