"""Compile: a manifest becomes a run plan, before anything is called (R5, R8, R14).

Everything that can be refused is refused here. A port whose type no registry
entry defines, a stage naming a kind nobody declared, a route to a stage that
does not exist, a format specification that cannot be compiled, a policy that
claims a power this prototype does not implement: each stops the compile with a
typed reason, and no model is reached.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping

from creib.errors import RecordError
from creib.strict_json import load_strict

from .attention import ATTENTION_OFF, AttentionPolicy, resolve_attention_policy
from .common import (
    KIND_SCHEMA_NAME,
    MANIFEST_SCHEMA_NAME,
    RUN_HEADER_DOMAIN,
    MiniError,
    array_value,
    content_id,
    digest_bytes,
    object_value,
    text,
    validate_instance,
)
from .evidence import BUILTIN_TIERS, TIER_EVIDENCE
from .formats import CompiledFormat, compile_format_spec
from .kinds import ArtifactKind, kind_from_dict
from .policy import DEFAULT_POLICY_ID, Grant, Policy, grant_from_dict, load_policy, with_grants
from .ports import (
    PortType,
    builtin_port_types,
    check_port_params,
    port_draws_kinds,
    port_draws_tiers,
    port_type_from_dict,
)
from .routing import Routing, routing_from_dict
from .executor import DEFAULT_ENDPOINT, endpoint_from_manifest
from .stops import STOP_NEVER, StopCondition, resolve_stop_condition


#: Every cycle ends with exactly one stage of this kind (R35 c).
VERDICT_KIND_ID = "mini.verdict.v1"

COMMITMENT_CALL_TWO = "two"
COMMITMENT_CALL_SINGLE = "single"

SEAT_MODEL = "model"
SEAT_MACHINE = "machine"
SEATS: tuple[str, ...] = (SEAT_MODEL, SEAT_MACHINE)


@dataclass(frozen=True)
class Stage:
    """One turn in a cycle. ``max_repeats`` is what bounds attention."""

    stage_id: str
    kind_id: str | None
    ports: tuple[str, ...]
    end: bool
    seat: str = SEAT_MODEL
    max_repeats: int = 0

    def to_dict(self) -> dict[str, object]:
        return {
            "stage_id": self.stage_id,
            "kind_id": self.kind_id,
            "ports": list(self.ports),
            "end": self.end,
            "seat": self.seat,
            "max_repeats": self.max_repeats,
        }


@dataclass(frozen=True)
class Cycles:
    """What ends a run: a cycle cap, a budget cap, a registered condition.

    ``max_completion_tokens`` and ``completion_tokens_per_call`` are declared together and
    turn the call cap from something read between cycles into something reserved before every
    send. They are absent by default and, when absent, are written to no compiled manifest, so
    a manifest compiled before they existed keeps the digest it had.
    """

    max_cycles: int
    max_calls: int | None
    stop_condition: StopCondition
    max_completion_tokens: int | None = None
    completion_tokens_per_call: int | None = None

    def to_dict(self) -> dict[str, object]:
        written: dict[str, object] = {
            "max_cycles": self.max_cycles,
            "max_calls": self.max_calls,
            "stop_condition": self.stop_condition.condition_id,
        }
        if self.max_completion_tokens is not None:
            written["max_completion_tokens"] = self.max_completion_tokens
        if self.completion_tokens_per_call is not None:
            written["completion_tokens_per_call"] = self.completion_tokens_per_call
        return written


@dataclass(frozen=True)
class Source:
    source_id: str
    tier: str
    raw: bytes

    def to_dict(self) -> dict[str, object]:
        return {"source_id": self.source_id, "tier": self.tier, "sha256": digest_bytes(self.raw)}


@dataclass(frozen=True)
class RunPlan:
    """Everything the loop needs, fixed before the first call."""

    manifest_id: str
    manifest_digest: str
    run_id: str
    genesis: str
    header: Mapping[str, Any]
    problem: str
    tiers: tuple[str, ...]
    port_types: Mapping[str, PortType]
    kinds: Mapping[str, ArtifactKind]
    formats: Mapping[str, CompiledFormat]
    stages: tuple[Stage, ...]
    routing: Routing
    cycles: Cycles
    policy: Policy
    policy_overrides: tuple[Mapping[str, Any], ...]
    attention: AttentionPolicy
    sources: tuple[Source, ...]
    #: The service a live run calls. Declared in the manifest, it is part of the header and so
    #: of the run's identity; absent, the shipped default applies and the header carries no key,
    #: so a manifest that says nothing keeps the identity it had before endpoints existed.
    endpoint: Any = DEFAULT_ENDPOINT
    endpoint_declared: bool = False

    def stage(self, stage_id: str) -> Stage:
        for item in self.stages:
            if item.stage_id == stage_id:
                return item
        raise MiniError("MINI_STAGE_UNKNOWN", f"no stage {stage_id!r} in this plan")


def _load_kind_entry(entry: Any, base_dir: Path, where: str) -> dict[str, Any]:
    if type(entry) is str:
        path = base_dir / entry
        try:
            raw = load_strict(path)
        except RecordError as error:
            raise MiniError("MINI_KIND_FILE_UNREADABLE", f"{where} names {entry!r}, which cannot be read: {error}") from error
        validate_instance(raw, KIND_SCHEMA_NAME, "MINI_KIND_FILE_UNREADABLE")
        return object_value(dict(raw)["kind"], f"{path}.kind")
    return object_value(entry, where)


def compile_manifest(path: Path, policy_dir: Path | None = None) -> RunPlan:
    """Read one manifest and compile it into a run plan."""

    if not isinstance(path, Path):
        raise TypeError("path must be pathlib.Path")
    try:
        raw_bytes = path.read_bytes()
        raw = load_strict(path)
    except (OSError, RecordError) as error:
        raise MiniError("MINI_MANIFEST_INVALID", f"cannot read the manifest at {path}: {error}") from error
    validate_instance(raw, MANIFEST_SCHEMA_NAME, "MINI_MANIFEST_INVALID")
    manifest = dict(raw)
    base_dir = path.parent
    manifest_digest = digest_bytes(raw_bytes)

    tiers: list[str] = list(BUILTIN_TIERS)
    for index, item in enumerate(manifest.get("tiers") or []):
        name = text(object_value(item, f"tiers[{index}]").get("tier"), f"tiers[{index}].tier", "MINI_TIER_DUPLICATE")
        if name in tiers:
            raise MiniError("MINI_TIER_DUPLICATE", f"tiers[{index}] declares {name!r}, which already exists")
        tiers.append(name)

    port_types: dict[str, PortType] = builtin_port_types()
    for index, item in enumerate(manifest.get("port_types") or []):
        declared = port_type_from_dict(item, f"port_types[{index}]")
        if declared.port_type in port_types:
            raise MiniError("MINI_PORT_TYPE_DUPLICATE", f"port_types[{index}] declares {declared.port_type!r}, which already exists")
        port_types[declared.port_type] = declared

    kinds: dict[str, ArtifactKind] = {}
    for index, item in enumerate(array_value(manifest.get("kinds"), "kinds")):
        kind = kind_from_dict(_load_kind_entry(item, base_dir, f"kinds[{index}]"), f"kinds[{index}]")
        if kind.kind_id in kinds:
            raise MiniError("MINI_KIND_DUPLICATE", f"kinds[{index}] declares {kind.kind_id!r}, which already exists")
        kinds[kind.kind_id] = kind

    for kind in kinds.values():
        for port in kind.input_ports:
            where = f"kind {kind.kind_id!r} port {port.port_id!r}"
            port_type = port_types.get(port.port_type)
            if port_type is None:
                raise MiniError(
                    "MINI_PORT_TYPE_UNKNOWN",
                    f"{where} names the port type {port.port_type!r}, which no registry entry defines",
                )
            check_port_params(port_type, port.params, where)
            for drawn in port_draws_kinds(port_type, port.params):
                if drawn not in kinds:
                    raise MiniError("MINI_KIND_UNKNOWN", f"{where} draws from the kind {drawn!r}, which nothing declares")
            for drawn in port_draws_tiers(port_type, port.params):
                if drawn not in tiers:
                    raise MiniError("MINI_TIER_UNKNOWN", f"{where} draws from the tier {drawn!r}, which nothing declares")

    formats = {
        kind_id: compile_format_spec(kind.format_spec, f"kind {kind_id!r} format")
        for kind_id, kind in kinds.items()
    }

    stages: list[Stage] = []
    seen_stages: set[str] = set()
    for index, item in enumerate(array_value(manifest.get("stages"), "stages")):
        entry = object_value(item, f"stages[{index}]")
        stage_id = text(entry.get("stage_id"), f"stages[{index}].stage_id", "MINI_STAGE_DUPLICATE")
        if stage_id in seen_stages:
            raise MiniError("MINI_STAGE_DUPLICATE", f"stages[{index}] declares {stage_id!r}, which already exists")
        seen_stages.add(stage_id)
        end = bool(entry.get("end", False))
        if end:
            stages.append(Stage(stage_id=stage_id, kind_id=None, ports=(), end=True))
            continue
        seat = entry.get("seat", SEAT_MODEL)
        if seat not in SEATS:
            raise MiniError("MINI_STAGE_UNKNOWN", f"stages[{index}].seat must be one of {list(SEATS)}, got {seat!r}")
        repeats = entry.get("max_repeats", 0)
        if type(repeats) is not int or not 0 <= repeats <= 16:
            raise MiniError("MINI_CYCLES_INVALID", f"stages[{index}].max_repeats must be a whole number from 0 to 16")
        kind_id = text(entry.get("kind_id"), f"stages[{index}].kind_id", "MINI_KIND_UNKNOWN")
        if kind_id not in kinds:
            raise MiniError("MINI_KIND_UNKNOWN", f"stages[{index}] names the kind {kind_id!r}, which nothing declares")
        ports = tuple(
            text(port, f"stages[{index}].ports[{position}]", "MINI_PORT_UNKNOWN")
            for position, port in enumerate(array_value(entry.get("ports") or [], f"stages[{index}].ports"))
        )
        declared_ports = {port.port_id for port in kinds[kind_id].input_ports}
        unknown = sorted(set(ports) - declared_ports)
        if unknown:
            raise MiniError("MINI_PORT_UNKNOWN", f"stages[{index}] names ports kind {kind_id!r} does not declare: {unknown}")
        stages.append(
            Stage(stage_id=stage_id, kind_id=kind_id, ports=ports, end=False, seat=str(seat), max_repeats=repeats)
        )
    if not stages[-1].end:
        raise MiniError("MINI_STAGE_NO_END", "the stage list must end in a stage marked end")
    for index, stage in enumerate(stages[:-1]):
        if stage.end:
            raise MiniError("MINI_STAGE_END_NOT_LAST", f"stages[{index}] is marked end but is not the last stage")
    verdicts = [index for index, stage in enumerate(stages) if stage.kind_id == VERDICT_KIND_ID]
    if not verdicts:
        raise MiniError(
            "MINI_VERDICT_MISSING",
            f"a cycle ends with one stage of kind {VERDICT_KIND_ID!r}; this stage list has none",
        )
    if len(verdicts) > 1:
        raise MiniError(
            "MINI_VERDICT_DUPLICATE",
            f"a cycle ends with ONE stage of kind {VERDICT_KIND_ID!r}; this stage list has {len(verdicts)}",
        )
    if verdicts[0] != len(stages) - 2:
        raise MiniError(
            "MINI_VERDICT_NOT_LAST",
            f"the {VERDICT_KIND_ID!r} stage must be the last stage before the end stage",
        )

    routing = routing_from_dict(manifest.get("routing"), "routing")
    stage_ids = {stage.stage_id: stage for stage in stages}
    for kind_id, destinations in routing.artifacts.items():
      for destination in destinations:
        if kind_id not in kinds:
            raise MiniError("MINI_ROUTE_INVALID", f"routing names the kind {kind_id!r}, which nothing declares")
        if destination.target == "port":
            target_stage = stage_ids.get(str(destination.stage_id))
            if target_stage is None or target_stage.kind_id is None:
                raise MiniError("MINI_ROUTE_INVALID", f"routing sends {kind_id!r} to the stage {destination.stage_id!r}, which is not a producing stage")
            if str(destination.port_id) not in {port.port_id for port in kinds[target_stage.kind_id].input_ports}:
                raise MiniError("MINI_ROUTE_INVALID", f"routing sends {kind_id!r} to the port {destination.port_id!r}, which that stage's kind does not declare")
        if destination.target == "evidence_store" and str(destination.tier) not in tiers:
            raise MiniError("MINI_TIER_UNKNOWN", f"routing sends {kind_id!r} to the tier {destination.tier!r}, which nothing declares")
    for tier, destinations in routing.evidence.items():
      for destination in destinations:
        if tier not in tiers:
            raise MiniError("MINI_TIER_UNKNOWN", f"routing names the tier {tier!r}, which nothing declares")
        if destination.target == "port_type" and str(destination.port_type) not in port_types:
            raise MiniError("MINI_ROUTE_INVALID", f"routing sends the tier {tier!r} to the port type {destination.port_type!r}, which nothing declares")

    cycles_raw = object_value(manifest.get("cycles") or {}, "cycles", "MINI_CYCLES_INVALID")
    max_cycles = cycles_raw.get("max_cycles", 1)
    if type(max_cycles) is not int or max_cycles < 1:
        raise MiniError("MINI_CYCLES_INVALID", "cycles.max_cycles must be a whole number of cycles, at least 1")
    max_calls = cycles_raw.get("max_calls")
    if max_calls is not None and (type(max_calls) is not int or max_calls < 1):
        raise MiniError("MINI_CYCLES_INVALID", "cycles.max_calls must be a whole number of calls, at least 1")
    max_completion_tokens = cycles_raw.get("max_completion_tokens")
    if max_completion_tokens is not None and (type(max_completion_tokens) is not int or max_completion_tokens < 1):
        raise MiniError("MINI_CYCLES_INVALID", "cycles.max_completion_tokens must be a whole number of tokens, at least 1")
    per_call = cycles_raw.get("completion_tokens_per_call")
    if per_call is not None and (type(per_call) is not int or per_call < 1):
        raise MiniError("MINI_CYCLES_INVALID", "cycles.completion_tokens_per_call must be a whole number of tokens, at least 1")
    if (max_completion_tokens is None) != (per_call is None):
        raise MiniError(
            "MINI_CYCLES_INVALID",
            "cycles.max_completion_tokens and cycles.completion_tokens_per_call are declared together or not at all: "
            "a total with no per-call allowance cannot be reserved before a send, and an allowance with no total bounds nothing",
        )
    if max_completion_tokens is not None and per_call is not None and per_call > max_completion_tokens:
        raise MiniError(
            "MINI_CYCLES_INVALID",
            "cycles.completion_tokens_per_call may not exceed cycles.max_completion_tokens; the first send could never be reserved",
        )
    cycles = Cycles(
        max_cycles=max_cycles,
        max_calls=max_calls,
        max_completion_tokens=max_completion_tokens,
        completion_tokens_per_call=per_call,
        stop_condition=resolve_stop_condition(
            text(cycles_raw.get("stop_condition", STOP_NEVER), "cycles.stop_condition", "MINI_STOP_CONDITION_UNKNOWN")
        ),
    )

    policy_raw = manifest.get("policy") or {}
    base_id = policy_raw.get("base", DEFAULT_POLICY_ID)
    policy = load_policy(text(base_id, "policy.base", "MINI_POLICY_UNKNOWN"), policy_dir)
    grants_raw = array_value(policy_raw.get("grants") or [], "policy.grants", "MINI_POLICY_UNKNOWN")
    overrides = tuple(object_value(item, f"policy.grants[{index}]", "MINI_POLICY_UNKNOWN") for index, item in enumerate(grants_raw))
    grants: list[Grant] = []
    for index, item in enumerate(overrides):
        grant = grant_from_dict(item, f"policy.grants[{index}]")
        if grant.kind_id not in kinds:
            raise MiniError("MINI_KIND_UNKNOWN", f"policy.grants[{index}] names the kind {grant.kind_id!r}, which nothing declares")
        grants.append(grant)
    policy = with_grants(policy, tuple(grants))

    attention_raw = manifest.get("attention") or {}
    attention = resolve_attention_policy(text(attention_raw.get("policy", ATTENTION_OFF), "attention.policy", "MINI_ATTENTION_POLICY_UNKNOWN"))

    sources: list[Source] = []
    seen_sources: set[str] = set()
    for index, item in enumerate(manifest.get("sources") or []):
        entry = object_value(item, f"sources[{index}]", "MINI_SOURCE_INVALID")
        source_id = text(entry.get("source_id"), f"sources[{index}].source_id", "MINI_SOURCE_INVALID")
        if source_id in seen_sources:
            raise MiniError("MINI_SOURCE_INVALID", f"sources[{index}] declares {source_id!r}, which already exists")
        seen_sources.add(source_id)
        has_text, has_path = "text" in entry, "path" in entry
        if has_text == has_path:
            raise MiniError("MINI_SOURCE_INVALID", f"sources[{index}] must carry exactly one of text or path")
        if has_text:
            body = text(entry["text"], f"sources[{index}].text", "MINI_SOURCE_INVALID").encode("utf-8")
        else:
            source_path = base_dir / text(entry["path"], f"sources[{index}].path", "MINI_SOURCE_INVALID")
            try:
                body = source_path.read_bytes()
            except OSError as error:
                raise MiniError("MINI_SOURCE_INVALID", f"sources[{index}] names {source_path}, which cannot be read: {error}") from error
        tier = entry.get("tier", TIER_EVIDENCE)
        if tier not in tiers:
            raise MiniError("MINI_TIER_UNKNOWN", f"sources[{index}] is tagged {tier!r}, which nothing declares")
        sources.append(Source(source_id=source_id, tier=str(tier), raw=body))

    endpoint_declared = manifest.get("endpoint") is not None
    endpoint = endpoint_from_manifest(manifest["endpoint"]) if endpoint_declared else DEFAULT_ENDPOINT

    manifest_id = text(manifest.get("manifest_id"), "manifest_id")
    problem = text(manifest.get("problem"), "problem")
    header: dict[str, Any] = {
        "manifest_id": manifest_id,
        "manifest_digest": manifest_digest,
        "problem": problem,
        "tiers": list(tiers),
        "port_types": [port_types[name].to_dict() for name in sorted(port_types)],
        "kinds": [kinds[name].to_dict() for name in sorted(kinds)],
        "stages": [stage.to_dict() for stage in stages],
        "routing": routing.to_dict(),
        "cycles": cycles.to_dict(),
        "policy": policy.to_dict(),
        "attention": attention.policy_id,
        "sources": [source.to_dict() for source in sources],
        **({"endpoint": endpoint.to_dict()} if endpoint_declared else {}),
    }
    genesis = content_id(RUN_HEADER_DOMAIN, header)
    return RunPlan(
        manifest_id=manifest_id,
        manifest_digest=manifest_digest,
        run_id=genesis[:16],
        genesis=genesis,
        header=header,
        problem=problem,
        tiers=tuple(tiers),
        port_types=port_types,
        kinds=kinds,
        formats=formats,
        stages=tuple(stages),
        routing=routing,
        cycles=cycles,
        policy=policy,
        policy_overrides=overrides,
        attention=attention,
        sources=tuple(sources),
        endpoint=endpoint,
        endpoint_declared=endpoint_declared,
    )

files.src/creib/forge/mini/openkernels.py:
"""Kernels a proposer names rather than a person registers (mini register M24).

A ``Kernel`` is a registered callable, so until now the boundary points a proposer could name were
exactly the ones somebody had written a ``register_kernel`` call for: ten at runtime. The space of
boundary points is not ten wide. This module lets a proposal name a function by its dotted path and
have it run, so what may be probed is bounded by an import rule that is written down rather than by
a list somebody curated.

Three bounds, declared rather than hidden:

- **The module allowlist.** Only the reading surface of the conformance harness. ``runner`` drives
  runs, ``executor`` calls an endpoint, ``common`` creates directories; a kernel is supposed to be a
  question about a reply, not an action, and this is the crudest honest way to say so. It is a
  bound, not a proof of purity: a function inside the allowlist may still do something surprising.
- **One argument.** ``Kernel.verdict`` is ``Callable[[str], str]``. A function of a variant, a key,
  two replies or a run's history cannot be reached this way, and that exclusion is the same one
  ``conformance_kernels`` already names.
- **A raise is unreadable, never a move.** Most of these functions raise on most inputs. Scoring an
  exception as an answer would make every crash look like a boundary point, and at this width there
  would be thousands. ``unreadable`` is what M11 already says to do with a verdict the check could
  not produce, and an execution with it on either side is ``unrunnable``.
"""

from __future__ import annotations

import importlib
import inspect
from typing import Any, Callable

from .blindspot import Kernel, PAIR_EXECUTION_PREFIX, execute_pairs_with, resolve_kernel
from .common import MiniError
from .machines import MachineContext, MachineSeat, register_machine_seat

#: The one prefix a proposal writes to mean "resolve this by import, not from the registry".
OPEN_PREFIX = "open:"

#: The package every open kernel must live under.
OPEN_PACKAGE = "creib.forge.conformance."

#: The inherited reading surface, restricted to support modules shipped by MiniReason.
#: The outer conformance harness is intentionally absent from this standalone package.
OPEN_MODULES: tuple[str, ...] = (
    "corpus", "families", "oracle", "records", "routing", "spec", "units",
)

#: The verdict for a call that raised. Never equal to any answer a function returns, because no
#: ``repr`` starts with a space.
RAISED = " raised"

OPEN_MALFORMED = "MINI_OPEN_KERNEL_MALFORMED"
OPEN_MODULE_REFUSED = "MINI_OPEN_KERNEL_MODULE_REFUSED"
OPEN_NOT_FOUND = "MINI_OPEN_KERNEL_NOT_FOUND"
OPEN_NOT_CALLABLE = "MINI_OPEN_KERNEL_NOT_CALLABLE"
OPEN_ARITY = "MINI_OPEN_KERNEL_ARITY"


def is_open_kernel_id(kernel_id: str) -> bool:
    """Whether this id asks for import resolution. Anything else is the registry's business."""

    return kernel_id.startswith(OPEN_PREFIX)


def _answer(function: Callable[..., Any]) -> Callable[[str], str]:
    def verdict(text: str) -> str:
        try:
            return repr(function(text))
        except Exception:  # noqa: BLE001 - any raise is one verdict: the check could not answer
            return RAISED

    return verdict


def resolve_open_kernel(kernel_id: str) -> Kernel:
    """Build a kernel from ``open:creib.forge.conformance.<module>.<function>``.

    Every refusal below is a refusal the proposer can provoke by writing a path, so each is a
    ``MiniError`` with its own code rather than a crash inside the seat.
    """

    if not is_open_kernel_id(kernel_id):
        raise MiniError(OPEN_MALFORMED, f"an open kernel id begins {OPEN_PREFIX!r}; got {kernel_id!r}")
    path = kernel_id[len(OPEN_PREFIX):]
    if not path.startswith(OPEN_PACKAGE) or path.count(".") < OPEN_PACKAGE.count("."):
        raise MiniError(
            OPEN_MALFORMED,
            f"an open kernel path is {OPEN_PACKAGE}<module>.<function>; got {path!r}",
        )
    rest = path[len(OPEN_PACKAGE):]
    module_name, _, function_name = rest.partition(".")
    if not function_name or "." in function_name:
        raise MiniError(
            OPEN_MALFORMED,
            f"an open kernel path names one module and one function; got {rest!r}",
        )
    if module_name not in OPEN_MODULES:
        raise MiniError(
            OPEN_MODULE_REFUSED,
            f"module {module_name!r} is not on the open list; allowed: {list(OPEN_MODULES)}",
        )
    module = importlib.import_module(f"{OPEN_PACKAGE}{module_name}")
    try:
        function = getattr(module, function_name)
    except AttributeError as error:
        raise MiniError(
            OPEN_NOT_FOUND,
            f"{module_name!r} has no {function_name!r}",
        ) from error
    if not inspect.isfunction(function):
        raise MiniError(OPEN_NOT_CALLABLE, f"{rest!r} is not a function")
    # No guard on ``signature`` raising: ``isfunction`` has already excluded the builtins and C
    # callables it raises for, so a guard here would be a refusal site no test could reach, which
    # the deletion sweep would rightly name.
    signature = inspect.signature(function)
    required = [
        parameter
        for parameter in signature.parameters.values()
        if parameter.default is inspect.Parameter.empty
        and parameter.kind in (parameter.POSITIONAL_ONLY, parameter.POSITIONAL_OR_KEYWORD)
    ]
    if len(required) != 1:
        raise MiniError(
            OPEN_ARITY,
            f"{rest!r} takes {len(required)} required arguments; a kernel takes one string",
        )
    return Kernel(
        kernel_id=kernel_id,
        description=f"{rest}, resolved by import",
        verdict=_answer(function),
        unreadable=RAISED,
    )


def open_kernel_brief() -> str:
    """What a proposer is told: the rule for forming a path, and the modules. Never the functions."""

    modules = "\n".join(f"- {OPEN_PACKAGE}{name}" for name in OPEN_MODULES)
    return (
        "A kernel id may instead be written "
        f"{OPEN_PREFIX}{OPEN_PACKAGE}<module>.<function>, naming any function of one string in one "
        "of these modules of the harness under test. No list of functions is given: read the source "
        "and choose. A function that raises on a text has not answered, and a pair on which either "
        "side raised is not a move.\n\n"
        f"{modules}\n"
    )


#: The seat a manifest names to get open kernels. The registry seat, ``mini.pair-execution.v1``, is
#: untouched, so every manifest written before this module is byte-for-byte unaffected and an open
#: answer space is something a run asks for rather than something it inherits.
PAIR_EXECUTION_OPEN_KIND = f"{PAIR_EXECUTION_PREFIX}open.v1"


#: Configuration a two-argument check takes in this codebase. A kernel is a function of one string,
#: so a check whose second argument is a fixed table is unreachable without this: CREATIVITY-ARMS-1
#: found the loop starved because every conjecture about such a check came back unrunnable, and a
#: criticism stage fed refusals is criticising the machinery rather than the subject.
SECOND_ARGUMENT: dict[str, str] = {
    "refusal_phrase_in": "creib.forge.mini.conformance_kernels.REFUSAL_PHRASES",
}


def _with_second_argument(function: Any, name: str) -> Callable[[str], str] | None:
    """A one-string view of a two-argument check, when its second argument is declared above."""

    target = SECOND_ARGUMENT.get(name)
    if target is None:
        return None
    holder, _, attribute = target.rpartition(".")
    value = getattr(importlib.import_module(holder), attribute)
    return lambda text: function(text, value)


def _candidate(path: str) -> Kernel | None:
    """One resolution attempt: the path as given, then with its declared second argument bound."""

    try:
        return resolve_open_kernel(path)
    except MiniError as error:
        if error.code != OPEN_ARITY:
            return None
    inner = path[len(OPEN_PREFIX):]
    module_name, _, function_name = inner.rpartition(".")
    function = getattr(importlib.import_module(module_name), function_name, None)
    bound = _with_second_argument(function, function_name) if function is not None else None
    if bound is None:
        return None
    return Kernel(kernel_id=path, description=f"{inner}, second argument declared",
                  verdict=_answer_of(bound), unreadable=RAISED)


def relocate(kernel_id: str) -> str | None:
    """The same function name under another open module, when its stated module does not hold it.

    A conjecture that names the right function in the wrong file is misfiled, not false, and
    refusing it teaches a criticism stage nothing about the subject. A candidate that needs its
    second argument bound counts as found: the two widenings have to compose, and the first version
    of this function rejected exactly the case both were written for.
    """

    if not is_open_kernel_id(kernel_id):
        return None
    name = kernel_id.rpartition(".")[2]
    for module_name in OPEN_MODULES:
        candidate = f"{OPEN_PREFIX}{OPEN_PACKAGE}{module_name}.{name}"
        if candidate != kernel_id and _candidate(candidate) is not None:
            return candidate
    return None


def resolve_any_kernel(kernel_id: str) -> Kernel:
    """The registry first, then import, then a declared second argument, then another module.

    The widenings after the first are ones CREATIVITY-ARMS-1 measured the need for: they turn a
    claim the executor would have refused into a result the loop can read. Applied to every arm
    equally, and an unknown name is still refused.
    """

    if not is_open_kernel_id(kernel_id):
        return resolve_kernel(kernel_id)
    direct = _candidate(kernel_id)
    if direct is not None:
        return direct
    elsewhere = relocate(kernel_id)
    if elsewhere is not None:
        moved = _candidate(elsewhere)
        if moved is not None:
            return moved
    return resolve_open_kernel(kernel_id)


def _answer_of(call: Callable[[str], Any]) -> Callable[[str], str]:
    def verdict(text: str) -> str:
        try:
            return repr(call(text))
        except Exception:  # noqa: BLE001 - any raise is one verdict: the check could not answer
            return RAISED

    return verdict


def _execute_pairs_open(context: MachineContext) -> str:
    return execute_pairs_with(context, resolve_any_kernel, PAIR_EXECUTION_OPEN_KIND)


PAIR_EXECUTION_OPEN_SEAT = register_machine_seat(
    MachineSeat(
        PAIR_EXECUTION_OPEN_KIND,
        "Runs pair proposals whose kernel may be any function of one string named by import path.",
        _execute_pairs_open,
    )
)

files.src/creib/forge/mini/policy.py:
"""Permission and authorisation: what a stage may read, write, and change (R17).

A shipped document states the defaults; a run adds grants. Read as three
sentences: a stage may read exactly the ports its kind declares and its stage
names; it may write its own output, the evidence store, and scratch, but may
not push into another stage's input port; and its output changes nothing about
any other artifact's standing.

That last sentence is the one this prototype cannot yet vary. The slot exists
so a later policy can grant a standing, and any value other than "nothing" is
refused at compile rather than accepted and quietly ignored.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping

from creib.errors import RecordError
from creib.strict_json import load_strict

from .common import (
    MINI_POLICY_DIR,
    POLICY_SCHEMA_NAME,
    MiniError,
    array_value,
    object_value,
    text,
)
from .routing import ARTIFACT_TARGETS, Destination, destination_from_dict

DEFAULT_POLICY_ID = "mini.policy.default.v1"
READ_MODES: tuple[str, ...] = ("declared_ports",)
WRITE_MODES: tuple[str, ...] = ("own_output", "evidence_store", "scratch", "nowhere")
CHANGES_NOTHING = "nothing"


@dataclass(frozen=True)
class PolicyDefaults:
    read: str
    write: tuple[str, ...]
    changes: str

    def to_dict(self) -> dict[str, object]:
        return {"read": self.read, "write": list(self.write), "changes": self.changes}


@dataclass(frozen=True)
class Grant:
    kind_id: str
    may_read_port_types: tuple[str, ...] | None
    may_write: tuple[Destination, ...]

    def to_dict(self) -> dict[str, object]:
        return {
            "kind_id": self.kind_id,
            "may_read_port_types": None if self.may_read_port_types is None else list(self.may_read_port_types),
            "may_write": [item.to_dict() for item in self.may_write],
        }


@dataclass(frozen=True)
class Policy:
    policy_id: str
    defaults: PolicyDefaults
    grants: tuple[Grant, ...]

    def grant_for(self, kind_id: str) -> Grant | None:
        for item in self.grants:
            if item.kind_id == kind_id:
                return item
        return None

    def may_read(self, kind_id: str, port_type: str) -> bool:
        grant = self.grant_for(kind_id)
        if grant is not None and grant.may_read_port_types is not None:
            return port_type in grant.may_read_port_types
        return self.defaults.read == "declared_ports"

    def may_write(self, kind_id: str, destination: Destination) -> bool:
        if destination.target in self.defaults.write:
            return True
        grant = self.grant_for(kind_id)
        if grant is None:
            return False
        for allowed in grant.may_write:
            if (
                allowed.target == destination.target
                and allowed.stage_id == destination.stage_id
                and allowed.port_id == destination.port_id
            ):
                return True
        return False

    def to_dict(self) -> dict[str, object]:
        return {
            "policy_id": self.policy_id,
            "defaults": self.defaults.to_dict(),
            "grants": [item.to_dict() for item in self.grants],
        }


def grant_from_dict(raw: Any, where: str) -> Grant:
    entry = object_value(raw, where, "MINI_POLICY_UNKNOWN")
    read_raw = entry.get("may_read_port_types")
    read = (
        None
        if read_raw is None
        else tuple(
            text(item, f"{where}.may_read_port_types[{index}]", "MINI_POLICY_UNKNOWN")
            for index, item in enumerate(array_value(read_raw, f"{where}.may_read_port_types", "MINI_POLICY_UNKNOWN"))
        )
    )
    write_raw = array_value(entry.get("may_write") or [], f"{where}.may_write", "MINI_POLICY_UNKNOWN")
    return Grant(
        kind_id=text(entry.get("kind_id"), f"{where}.kind_id", "MINI_POLICY_UNKNOWN"),
        may_read_port_types=read,
        may_write=tuple(
            destination_from_dict(item, f"{where}.may_write[{index}]", ARTIFACT_TARGETS)
            for index, item in enumerate(write_raw)
        ),
    )


def policy_from_dict(raw: Any, where: str) -> Policy:
    entry = object_value(raw, where, "MINI_POLICY_UNKNOWN")
    defaults_raw = object_value(entry.get("defaults"), f"{where}.defaults", "MINI_POLICY_UNKNOWN")
    read = text(defaults_raw.get("read"), f"{where}.defaults.read", "MINI_POLICY_DEFAULT_UNKNOWN")
    if read not in READ_MODES:
        raise MiniError("MINI_POLICY_DEFAULT_UNKNOWN", f"{where}.defaults.read must be one of {list(READ_MODES)}, got {read!r}")
    write_raw = array_value(defaults_raw.get("write"), f"{where}.defaults.write", "MINI_POLICY_DEFAULT_UNKNOWN")
    write = tuple(text(item, f"{where}.defaults.write[{index}]", "MINI_POLICY_DEFAULT_UNKNOWN") for index, item in enumerate(write_raw))
    unknown = sorted(set(write) - set(WRITE_MODES))
    if unknown:
        raise MiniError("MINI_POLICY_DEFAULT_UNKNOWN", f"{where}.defaults.write names modes nothing implements: {unknown}")
    changes = text(defaults_raw.get("changes"), f"{where}.defaults.changes", "MINI_POLICY_CHANGE_UNSUPPORTED")
    if changes != CHANGES_NOTHING:
        raise MiniError(
            "MINI_POLICY_CHANGE_UNSUPPORTED",
            f"{where}.defaults.changes is {changes!r}; this prototype mints no standing and implements only {CHANGES_NOTHING!r}",
        )
    grants_raw = array_value(entry.get("grants") or [], f"{where}.grants", "MINI_POLICY_UNKNOWN")
    return Policy(
        policy_id=text(entry.get("policy_id"), f"{where}.policy_id", "MINI_POLICY_UNKNOWN"),
        defaults=PolicyDefaults(read=read, write=write, changes=changes),
        grants=tuple(grant_from_dict(item, f"{where}.grants[{index}]") for index, item in enumerate(grants_raw)),
    )


def load_policy(policy_id: str, directory: Path | None = None) -> Policy:
    """Load one shipped policy document by its id."""

    base = MINI_POLICY_DIR if directory is None else directory
    path = base / f"{policy_id}.json"
    try:
        raw = load_strict(path)
    except RecordError as error:
        raise MiniError("MINI_POLICY_UNKNOWN", f"no policy document {policy_id!r} at {path}: {error}") from error
    from .common import validate_instance

    validate_instance(raw, POLICY_SCHEMA_NAME, "MINI_POLICY_UNKNOWN")
    policy = policy_from_dict(raw, str(path))
    if policy.policy_id != policy_id:
        raise MiniError("MINI_POLICY_UNKNOWN", f"{path} declares the policy id {policy.policy_id!r}, not {policy_id!r}")
    return policy


def with_grants(policy: Policy, grants: tuple[Grant, ...]) -> Policy:
    """A run's overrides: the base document plus this run's extra grants."""

    merged: list[Grant] = list(policy.grants)
    for grant in grants:
        merged = [item for item in merged if item.kind_id != grant.kind_id] + [grant]
    return Policy(policy_id=policy.policy_id, defaults=policy.defaults, grants=tuple(merged))

files.src/creib/forge/mini/ports.py:
"""Input port types: where a port draws from, and how it renders (R5).

Four types ship. A manifest adds more at compile time by declaring a name, the
artifact kinds or the evidence tiers the type draws from, and a rendering rule
from a closed vocabulary. Nothing in this module knows any particular artifact
kind: a port type names kinds as data, so a kind invented in a manifest is
drawn from by a port type declared in the same manifest, and no code changes.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping

from .common import MiniError, array_value, object_value, text

SOURCES: tuple[str, ...] = ("problem", "artifacts", "evidence", "scratch")
RENDER_RULES: tuple[str, ...] = ("text", "list_bodies", "list_bodies_and_commitments", "legend")

PORT_TYPE_PROBLEM = "problem"
PORT_TYPE_EVIDENCE_LEGEND = "evidence_legend"
PORT_TYPE_ARTIFACTS_OF_KIND = "artifacts_of_kind"
PORT_TYPE_SCRATCH = "scratch"


@dataclass(frozen=True)
class PortType:
    """One registered input port type."""

    port_type: str
    source: str
    kinds: tuple[str, ...]
    tiers: tuple[str, ...]
    render_rule: str
    header: str
    required_params: tuple[str, ...]
    builtin: bool

    def to_dict(self) -> dict[str, object]:
        return {
            "port_type": self.port_type,
            "source": self.source,
            "kinds": list(self.kinds),
            "tiers": list(self.tiers),
            "render_rule": self.render_rule,
            "header": self.header,
            "builtin": self.builtin,
        }


BUILTIN_PORT_TYPES: tuple[PortType, ...] = (
    PortType(PORT_TYPE_PROBLEM, "problem", (), (), "text", "The problem", (), True),
    PortType(PORT_TYPE_EVIDENCE_LEGEND, "evidence", (), (), "legend", "Evidence", ("tiers",), True),
    PortType(PORT_TYPE_ARTIFACTS_OF_KIND, "artifacts", (), (), "list_bodies_and_commitments", "Artifacts so far", ("kind_id",), True),
    PortType(PORT_TYPE_SCRATCH, "scratch", (), (), "list_bodies", "Scratch", ("destination",), True),
)

_RULE_SOURCES: Mapping[str, tuple[str, ...]] = {
    "text": ("problem", "artifacts", "scratch"),
    "list_bodies": ("artifacts", "scratch"),
    "list_bodies_and_commitments": ("artifacts", "scratch"),
    "legend": ("evidence",),
}


def builtin_port_types() -> dict[str, PortType]:
    return {item.port_type: item for item in BUILTIN_PORT_TYPES}


def port_type_from_dict(raw: Any, where: str) -> PortType:
    """Read one manifest-declared port type."""

    entry = object_value(raw, where)
    name = text(entry.get("port_type"), f"{where}.port_type", "MINI_PORT_TYPE_DUPLICATE")
    draws = object_value(entry.get("draws_from"), f"{where}.draws_from", "MINI_PORT_TYPE_DRAWS_FROM_INVALID")
    has_kinds = "artifact_kinds" in draws
    has_tiers = "evidence_tiers" in draws
    if has_kinds == has_tiers:
        raise MiniError(
            "MINI_PORT_TYPE_DRAWS_FROM_INVALID",
            f"{where}.draws_from must name exactly one of artifact_kinds or evidence_tiers",
        )
    kinds: tuple[str, ...] = ()
    tiers: tuple[str, ...] = ()
    if has_kinds:
        items = array_value(draws["artifact_kinds"], f"{where}.draws_from.artifact_kinds", "MINI_PORT_TYPE_DRAWS_FROM_INVALID")
        kinds = tuple(text(item, f"{where}.draws_from.artifact_kinds[{index}]", "MINI_PORT_TYPE_DRAWS_FROM_INVALID") for index, item in enumerate(items))
        source = "artifacts"
    else:
        items = array_value(draws["evidence_tiers"], f"{where}.draws_from.evidence_tiers", "MINI_PORT_TYPE_DRAWS_FROM_INVALID")
        tiers = tuple(text(item, f"{where}.draws_from.evidence_tiers[{index}]", "MINI_PORT_TYPE_DRAWS_FROM_INVALID") for index, item in enumerate(items))
        source = "evidence"
    if not (kinds or tiers):
        raise MiniError("MINI_PORT_TYPE_DRAWS_FROM_INVALID", f"{where}.draws_from must not be empty")
    render = object_value(entry.get("render"), f"{where}.render", "MINI_RENDER_RULE_UNKNOWN")
    rule = text(render.get("rule"), f"{where}.render.rule", "MINI_RENDER_RULE_UNKNOWN")
    if rule not in RENDER_RULES:
        raise MiniError("MINI_RENDER_RULE_UNKNOWN", f"{where}.render.rule must be one of {list(RENDER_RULES)}, got {rule!r}")
    if source not in _RULE_SOURCES[rule]:
        raise MiniError(
            "MINI_PORT_TYPE_DRAWS_FROM_INVALID",
            f"{where} renders with {rule!r}, which cannot render what it draws from",
        )
    header = render.get("header") or name
    return PortType(name, source, kinds, tiers, rule, text(header, f"{where}.render.header", "MINI_RENDER_RULE_UNKNOWN"), (), False)


def check_port_params(port_type: PortType, params: Mapping[str, Any], where: str) -> None:
    """Refuse a port whose parameters do not fit its type."""

    if not port_type.builtin:
        if params:
            raise MiniError("MINI_PORT_PARAMS_INVALID", f"{where} takes no parameters: {port_type.port_type!r} fixes what it draws from")
        return
    unknown = sorted(set(params) - set(port_type.required_params))
    if unknown:
        raise MiniError("MINI_PORT_PARAMS_INVALID", f"{where} carries parameters {port_type.port_type!r} does not take: {unknown}")
    for name in port_type.required_params:
        if name not in params:
            raise MiniError("MINI_PORT_PARAMS_INVALID", f"{where} must carry the parameter {name!r}")
    if "tiers" in params:
        items = array_value(params["tiers"], f"{where}.params.tiers", "MINI_PORT_PARAMS_INVALID")
        if not items:
            raise MiniError("MINI_PORT_PARAMS_INVALID", f"{where}.params.tiers must not be empty")
        for index, item in enumerate(items):
            text(item, f"{where}.params.tiers[{index}]", "MINI_PORT_PARAMS_INVALID")
    for name in ("kind_id", "destination"):
        if name in params:
            text(params[name], f"{where}.params.{name}", "MINI_PORT_PARAMS_INVALID")


def port_draws_kinds(port_type: PortType, params: Mapping[str, Any]) -> tuple[str, ...]:
    if port_type.source != "artifacts":
        return ()
    if port_type.builtin:
        return (str(params["kind_id"]),)
    return port_type.kinds


def port_draws_tiers(port_type: PortType, params: Mapping[str, Any]) -> tuple[str, ...]:
    if port_type.source != "evidence":
        return ()
    if port_type.builtin:
        return tuple(str(item) for item in params["tiers"])
    return port_type.tiers

files.src/creib/forge/mini/routing.py:
"""Where an artifact's contents go, and where a batch of evidence goes (R15, R16).

Two lists of rules, both written by the operator. One rule serves both. A port's default draw is
everything of the kinds or tiers its type names, so an ordinary conjecturer to
critic to end run needs no routing at all. A declared route REPLACES that
default for the one kind or tier it names, and leaves everything else on the
default; a push is additive on top of whatever the route allows, which is why a
kind or tier may carry more than one route.

A kind or tier routed nowhere reaches NO port. It stays in the store, which is
exactly the condition a withheld citation reports, and it is shown to nobody.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping

from .common import MiniError, object_value, text

ARTIFACT_TARGETS: tuple[str, ...] = ("port", "evidence_store", "scratch", "nowhere")
EVIDENCE_TARGETS: tuple[str, ...] = ("port_type", "scratch", "nowhere")


@dataclass(frozen=True)
class Destination:
    """One routing destination, read from the manifest."""

    target: str
    stage_id: str | None = None
    port_id: str | None = None
    port_type: str | None = None
    tier: str | None = None
    destination: str | None = None

    def to_dict(self) -> dict[str, object]:
        return {
            key: value
            for key, value in (
                ("target", self.target),
                ("stage_id", self.stage_id),
                ("port_id", self.port_id),
                ("port_type", self.port_type),
                ("tier", self.tier),
                ("destination", self.destination),
            )
            if value is not None
        }


def destination_from_dict(raw: Any, where: str, admitted: tuple[str, ...]) -> Destination:
    entry = object_value(raw, where, "MINI_ROUTE_INVALID")
    target = text(entry.get("target"), f"{where}.target", "MINI_ROUTE_TARGET_UNKNOWN")
    if target not in admitted:
        raise MiniError("MINI_ROUTE_TARGET_UNKNOWN", f"{where}.target must be one of {list(admitted)}, got {target!r}")
    destination = Destination(
        target=target,
        stage_id=entry.get("stage_id"),
        port_id=entry.get("port_id"),
        port_type=entry.get("port_type"),
        tier=entry.get("tier"),
        destination=entry.get("destination"),
    )
    required: Mapping[str, tuple[str, ...]] = {
        "port": ("stage_id", "port_id"),
        "port_type": ("port_type",),
        "scratch": ("destination",),
        "evidence_store": ("tier",),
        "nowhere": (),
    }
    for name in required[target]:
        if getattr(destination, name) is None:
            raise MiniError("MINI_ROUTE_INVALID", f"{where} routes to {target!r} and must name {name!r}")
    return destination


@dataclass(frozen=True)
class Routing:
    """The declared routes; anything unnamed keeps the default draw."""

    artifacts: Mapping[str, tuple[Destination, ...]]
    evidence: Mapping[str, tuple[Destination, ...]]

    def for_artifact(self, kind_id: str) -> tuple[Destination, ...]:
        return self.artifacts.get(kind_id, ())

    def for_evidence(self, tier: str) -> tuple[Destination, ...]:
        return self.evidence.get(tier, ())

    def to_dict(self) -> dict[str, object]:
        return {
            "artifacts": {key: [item.to_dict() for item in self.artifacts[key]] for key in sorted(self.artifacts)},
            "evidence": {key: [item.to_dict() for item in self.evidence[key]] for key in sorted(self.evidence)},
        }


EMPTY_ROUTING = Routing(artifacts={}, evidence={})


def _collected(
    rules: Any, where: str, key: str, admitted: tuple[str, ...]
) -> dict[str, tuple[Destination, ...]]:
    """Group routes by the kind or tier they name; nowhere may not be combined."""

    collected: dict[str, list[Destination]] = {}
    for index, item in enumerate(rules or []):
        rule = object_value(item, f"{where}[{index}]", "MINI_ROUTE_INVALID")
        subject = text(rule.get(key), f"{where}[{index}].{key}", "MINI_ROUTE_INVALID")
        collected.setdefault(subject, []).append(
            destination_from_dict(rule.get("to"), f"{where}[{index}].to", admitted)
        )
    for subject, destinations in collected.items():
        targets = [destination.target for destination in destinations]
        if "nowhere" in targets and len(targets) > 1:
            raise MiniError(
                "MINI_ROUTE_INVALID",
                f"{where} routes {subject!r} nowhere and somewhere else; the union of nowhere and anything is not nowhere",
            )
    return {subject: tuple(destinations) for subject, destinations in collected.items()}


def routing_from_dict(raw: Any, where: str) -> Routing:
    if raw is None:
        return EMPTY_ROUTING
    entry = object_value(raw, where, "MINI_ROUTE_INVALID")
    return Routing(
        artifacts=_collected(entry.get("artifacts"), f"{where}.artifacts", "from_kind", ARTIFACT_TARGETS),
        evidence=_collected(entry.get("evidence"), f"{where}.evidence", "from_tier", EVIDENCE_TARGETS),
    )

files.src/creib/forge/mini/signals.py:
"""Signals: named quantities computed from the record, added by registration (R19).

A signal declares a name, a unit, and what it means; a function computes it from
state. Adding one is a registration, and nothing that consumes signals is
edited — an attention policy sees a new signal because it declares that it
reads it, never because a consumer learned about a subsystem.

Every shipped signal is keyed by an id the record already carries (a kind id, an
artifact id), so a kind nobody had invented when a signal was written still
appears in that signal's result.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable, Mapping

from .common import MiniError, identifier
from .evidence import CITATION_VERIFIED
from .log import MiniState

SIGNAL_ARTIFACTS_BY_KIND = "mini.signal.artifacts-by-kind"
SIGNAL_CITATIONS_VERIFIED = "mini.signal.citations-verified-by-artifact"
SIGNAL_UNANSWERED_BY_KIND = "mini.signal.unanswered-criticisms-by-kind"
SIGNAL_TOKENS_BY_KIND = "mini.signal.tokens-by-kind"
SIGNAL_CYCLE_COUNT = "mini.signal.cycle-count"
SIGNAL_ARTIFACTS_IN_LAST_CYCLE = "mini.signal.artifacts-in-last-cycle"


@dataclass(frozen=True)
class SignalDecl:
    """What a signal is: a name, a unit, and what it counts."""

    signal_id: str
    unit: str
    description: str


@dataclass(frozen=True)
class RegisteredSignal:
    declaration: SignalDecl
    compute: Callable[[MiniState], Any]


_REGISTRY: dict[str, RegisteredSignal] = {}


def register_signal(declaration: SignalDecl, compute: Callable[[MiniState], Any]) -> RegisteredSignal:
    identifier(declaration.signal_id, "signal_id", "MINI_SIGNAL_UNKNOWN")
    if declaration.signal_id in _REGISTRY:
        raise MiniError("MINI_SIGNAL_DUPLICATE", f"signal {declaration.signal_id!r} is already registered")
    registered = RegisteredSignal(declaration=declaration, compute=compute)
    _REGISTRY[declaration.signal_id] = registered
    return registered


def registered_signals() -> tuple[SignalDecl, ...]:
    return tuple(_REGISTRY[name].declaration for name in sorted(_REGISTRY))


def compute_signals(state: MiniState, signal_ids: tuple[str, ...]) -> dict[str, Any]:
    """Compute exactly the named signals."""

    values: dict[str, Any] = {}
    for name in signal_ids:
        try:
            registered = _REGISTRY[name]
        except KeyError as error:
            raise MiniError("MINI_SIGNAL_UNKNOWN", f"no signal {name!r} is registered; known: {sorted(_REGISTRY)}") from error
        values[name] = registered.compute(state)
    return values


def _artifacts_by_kind(state: MiniState) -> dict[str, int]:
    return dict(state.submissions_by_kind)


def _citations_verified(state: MiniState) -> dict[str, int]:
    return {
        artifact_id: sum(1 for item in record["citations"] if item.get("code") == CITATION_VERIFIED)
        for artifact_id, record in state.artifacts.items()
    }


def _unanswered_by_kind(state: MiniState) -> dict[str, int]:
    """Count, per kind, the artifacts about one of its artifacts that nothing answers.

    No kind is named here. An artifact that points at another through ``about``
    is a criticism of it for this purpose, and an artifact named in some other
    artifact's ``answers`` has been answered.
    """

    answered: set[str] = set()
    for record in state.artifacts.values():
        answered.update(record["answers"])
    counts: dict[str, int] = {}
    for artifact_id, record in state.artifacts.items():
        if artifact_id in answered:
            continue
        for target_id in record["about"]:
            target = state.artifacts.get(target_id)
            if target is None:
                continue
            key = str(target["kind_id"])
            counts[key] = counts.get(key, 0) + 1
    return counts


def _tokens_by_kind(state: MiniState) -> dict[str, int]:
    return dict(state.tokens_by_kind)


def _cycle_count(state: MiniState) -> int:
    """How many cycles the run has reached. A real cycle, not a guess at one."""

    return state.cycle


def _artifacts_in_last_cycle(state: MiniState) -> dict[str, int]:
    """How many artifacts each cycle produced, keyed by the cycle number."""

    counts: dict[str, int] = {}
    for record in state.artifacts.values():
        key = str(record.get("cycle", 0))
        counts[key] = counts.get(key, 0) + 1
    return counts


SHIPPED_SIGNALS: Mapping[str, str] = {
    SIGNAL_ARTIFACTS_BY_KIND: "artifacts",
    SIGNAL_CITATIONS_VERIFIED: "citations",
    SIGNAL_UNANSWERED_BY_KIND: "criticisms",
    SIGNAL_TOKENS_BY_KIND: "tokens",
    SIGNAL_CYCLE_COUNT: "cycles",
    SIGNAL_ARTIFACTS_IN_LAST_CYCLE: "artifacts",
}

register_signal(
    SignalDecl(SIGNAL_ARTIFACTS_BY_KIND, "artifacts", "How many artifacts of each kind the run has produced."),
    _artifacts_by_kind,
)
register_signal(
    SignalDecl(SIGNAL_CITATIONS_VERIFIED, "citations", "How many of each artifact's citations were verified."),
    _citations_verified,
)
register_signal(
    SignalDecl(SIGNAL_UNANSWERED_BY_KIND, "criticisms", "How many unanswered criticisms stand against each kind's artifacts."),
    _unanswered_by_kind,
)
register_signal(
    SignalDecl(SIGNAL_TOKENS_BY_KIND, "tokens", "How many reply tokens each kind has spent."),
    _tokens_by_kind,
)
register_signal(
    SignalDecl(SIGNAL_CYCLE_COUNT, "cycles", "How many cycles the run has reached."),
    _cycle_count,
)
register_signal(
    SignalDecl(SIGNAL_ARTIFACTS_IN_LAST_CYCLE, "artifacts", "How many artifacts each cycle produced, by cycle number."),
    _artifacts_in_last_cycle,
)

files.src/creib/forge/mini/stops.py:
"""When a run stops, decided by the host and never by a seat (R23).

Three things can end a run, and a seat's prose is none of them: a cycle cap, a
budget cap, and a registered stop condition. A stop condition is a function of
SIGNALS, declared and handed a view of exactly what it declared, for the same
reason an attention policy is: nothing that decides whether the run continues
may read the record directly, and no artifact's content may end a run by saying
so.

A stop condition is not attention. It decides whether there is another cycle;
attention decides what runs inside one.
"""

from __future__ import annotations

import inspect
from dataclasses import dataclass
from typing import Any, Callable, Mapping

from .attention import SignalView
from .common import MiniError

STOP_NEVER = "mini.stop.never"
STOP_NO_ARTIFACT_LAST_CYCLE = "mini.stop.no-artifact-last-cycle"
SIGNAL_ARTIFACTS_IN_LAST_CYCLE = "mini.signal.artifacts-in-last-cycle"
_SIGNATURE: tuple[str, ...] = ("signals", "cycle")


@dataclass(frozen=True)
class StopCondition:
    """One registered machine stop condition."""

    condition_id: str
    reads_signals: tuple[str, ...]
    description: str
    decide: Callable[[SignalView, int], str | None]


_REGISTRY: dict[str, StopCondition] = {}


def register_stop_condition(condition: StopCondition) -> StopCondition:
    """Register one condition, refusing a function that could take the record."""

    if condition.condition_id in _REGISTRY:
        raise MiniError(
            "MINI_STOP_CONDITION_DUPLICATE", f"stop condition {condition.condition_id!r} is already registered"
        )
    parameters = tuple(inspect.signature(condition.decide).parameters)
    if parameters != _SIGNATURE:
        raise MiniError(
            "MINI_STOP_CONDITION_SIGNATURE",
            f"stop condition {condition.condition_id!r} takes {list(parameters)}; it may take only {list(_SIGNATURE)}",
        )
    _REGISTRY[condition.condition_id] = condition
    return condition


def resolve_stop_condition(condition_id: str) -> StopCondition:
    try:
        return _REGISTRY[condition_id]
    except KeyError as error:
        raise MiniError(
            "MINI_STOP_CONDITION_UNKNOWN",
            f"no stop condition {condition_id!r} is registered; known: {sorted(_REGISTRY)}",
        ) from error


def registered_stop_conditions() -> tuple[StopCondition, ...]:
    return tuple(_REGISTRY[name] for name in sorted(_REGISTRY))


def should_stop(condition: StopCondition, signals: Mapping[str, Any], cycle: int) -> str | None:
    """Ask one condition whether the run stops before this cycle."""

    view = SignalView(signals, condition.reads_signals, condition.condition_id)
    return condition.decide(view, cycle)


def _never(signals: SignalView, cycle: int) -> str | None:
    return None


def _no_artifact_last_cycle(signals: SignalView, cycle: int) -> str | None:
    if cycle <= 1:
        return None
    produced = signals[SIGNAL_ARTIFACTS_IN_LAST_CYCLE]
    if int(produced.get(str(cycle - 1), 0) if isinstance(produced, dict) else produced) == 0:
        return "no artifact was produced in the cycle before this one"
    return None


NEVER = register_stop_condition(
    StopCondition(STOP_NEVER, (), "Never stop of its own accord. The default.", _never)
)

NO_ARTIFACT_LAST_CYCLE = register_stop_condition(
    StopCondition(
        STOP_NO_ARTIFACT_LAST_CYCLE,
        (SIGNAL_ARTIFACTS_IN_LAST_CYCLE,),
        "Stop when a whole cycle produced nothing.",
        _no_artifact_last_cycle,
    )
)

files.src/creib/forge/mini/windows.py:
"""How far back a port looks (R23).

A port declaration may carry a window, and what it draws is filtered by the
cycle coordinate the record already carries. The default is ``all``, so a
manifest that says nothing behaves as it did before cycles existed.

Supplied sources are batched before the first cycle and carry cycle 0, so
``this_cycle`` on an evidence port draws only what the run itself generated.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from .common import MiniError, object_value

WINDOW_ALL = "all"
WINDOW_THIS_CYCLE = "this_cycle"
WINDOW_PREVIOUS_CYCLE = "previous_cycle"
WINDOW_NAMES: tuple[str, ...] = (WINDOW_ALL, WINDOW_THIS_CYCLE, WINDOW_PREVIOUS_CYCLE)
_INVALID = "MINI_WINDOW_INVALID"


@dataclass(frozen=True)
class Window:
    """One port's reach back through the cycles."""

    name: str
    last_n: int | None = None

    def admits(self, produced_in: int, current_cycle: int) -> bool:
        if self.name == WINDOW_ALL:
            return True
        if self.name == WINDOW_THIS_CYCLE:
            return produced_in == current_cycle
        if self.name == WINDOW_PREVIOUS_CYCLE:
            return produced_in == current_cycle - 1
        return produced_in > current_cycle - int(self.last_n or 0)

    def to_dict(self) -> dict[str, object]:
        return {"window": self.name} if self.last_n is None else {"window": self.name, "last_n": self.last_n}


ALL = Window(WINDOW_ALL)


def window_from_dict(raw: Any, where: str) -> Window:
    """Read one port's window. Absent is ``all``."""

    if raw is None:
        return ALL
    if type(raw) is str:
        if raw not in WINDOW_NAMES:
            raise MiniError(_INVALID, f"{where} must be one of {list(WINDOW_NAMES)} or a last_n object, got {raw!r}")
        return Window(raw)
    entry = object_value(raw, where, _INVALID)
    if set(entry) != {"last_n"}:
        raise MiniError(_INVALID, f"{where} as an object must carry only last_n")
    value = entry["last_n"]
    if type(value) is not int or value < 1:
        raise MiniError(_INVALID, f"{where}.last_n must be a whole number of cycles, at least 1")
    return Window("last_n", value)

files.src/creib/forge/schema_validation.py:
"""Offline, fail-closed JSON Schema validation for the conformance harness.

Every schema in one directory is strict-loaded, checked against the JSON
Schema 2020-12 metaschema, and registered in a registry whose retrieval
function always fails, so validation can never fetch a schema over the
network. Local references must resolve inside that registry.

The checked catalog is memoised per process under a key made of the
directory path and the SHA-256 of every schema file's bytes. A cache hit
requires byte-identical schema files; any change misses the cache and
repeats the complete check. Caching removes repeated work; it never skips a
check that a changed input would need.
"""

from __future__ import annotations

from dataclasses import dataclass
import json
from pathlib import Path
import threading
from types import MappingProxyType
from typing import Any, Mapping
from urllib.parse import urljoin, urlsplit

from jsonschema import Draft202012Validator
from jsonschema.exceptions import SchemaError
from referencing import Registry, Resource
from referencing.exceptions import (
    CannotDetermineSpecification,
    InvalidAnchor,
    NoSuchAnchor,
    NoSuchResource,
    PointerToNowhere,
    Unresolvable,
    Unretrievable,
)

from creib.canonical import bytes_digest
from creib.errors import RecordError
from creib.strict_json import loads_strict


DEFAULT_SCHEMA_DIR = Path(__file__).resolve().parents[3] / "forge" / "conformance" / "schema"
_DRAFT_2020_12 = "https://json-schema.org/draft/2020-12/schema"
_FORBIDDEN_RESOURCE_KEYS = frozenset({"$anchor", "$dynamicAnchor", "$dynamicRef"})
_SINGLE_SCHEMA_KEYWORDS = frozenset(
    {"additionalProperties", "contains", "else", "if", "items", "not", "propertyNames", "then", "unevaluatedItems", "unevaluatedProperties"}
)
_SCHEMA_ARRAY_KEYWORDS = frozenset({"allOf", "anyOf", "oneOf", "prefixItems"})
_SCHEMA_MAP_KEYWORDS = frozenset({"$defs", "dependentSchemas", "patternProperties", "properties"})


def _deny_retrieval(uri: str) -> Resource[Any]:
    raise RecordError(f"schema retrieval is disabled; unregistered reference {uri!r}")


def _registry_from_schemas(schemas: Mapping[str, Mapping[str, Any]]) -> Registry[Any]:
    registry: Registry[Any] = Registry(retrieve=_deny_retrieval)
    for schema in schemas.values():
        registry = registry.with_resource(schema["$id"], Resource.from_contents(schema))
    return registry.crawl()


def _schema_references(node: Any, base_uri: str, path: str = "$"):
    """Yield (base_uri, reference) pairs for every ``$ref`` in a schema tree."""

    if isinstance(node, dict):
        forbidden = _FORBIDDEN_RESOURCE_KEYS & set(node)
        if forbidden:
            raise RecordError(f"schema uses unsupported keyword(s) {sorted(forbidden)} at {path}")
        if "$id" in node and path != "$":
            raise RecordError(f"nested $id is not supported at {path}")
        if "$ref" in node:
            if type(node["$ref"]) is not str:
                raise RecordError(f"$ref must be a string at {path}")
            yield base_uri, node["$ref"]
        for key, value in node.items():
            if key in _SINGLE_SCHEMA_KEYWORDS:
                yield from _schema_references(value, base_uri, f"{path}.{key}")
            elif key in _SCHEMA_ARRAY_KEYWORDS and isinstance(value, list):
                for index, item in enumerate(value):
                    yield from _schema_references(item, base_uri, f"{path}.{key}[{index}]")
            elif key in _SCHEMA_MAP_KEYWORDS and isinstance(value, dict):
                for name, item in value.items():
                    yield from _schema_references(item, base_uri, f"{path}.{key}.{name}")


def _stable_path(parts: Any) -> str:
    return "/" + "/".join(str(part) for part in parts)


@dataclass(frozen=True)
class LocalSchemaCatalog:
    """A checked, immutable view of a fail-closed local schema registry."""

    schema_dir: Path
    _schema_sources: Mapping[str, str]
    _checked_schemas: Mapping[str, Mapping[str, Any]]
    _checked_registry: Registry[Any]

    @property
    def schemas(self) -> Mapping[str, Mapping[str, Any]]:
        """Return a disposable snapshot; mutations cannot alter the catalog."""

        return MappingProxyType({name: loads_strict(source) for name, source in self._schema_sources.items()})

    @property
    def schema_names(self) -> tuple[str, ...]:
        return tuple(self._schema_sources)

    @property
    def registry(self) -> Registry[Any]:
        """The checked, retrieval-disabled registry; ``referencing`` registries are immutable."""

        return self._checked_registry

    def validator(self, schema_name: str) -> Draft202012Validator:
        if type(schema_name) is not str or not schema_name:
            raise RecordError("schema_name must be a non-empty string")
        try:
            schema = self._checked_schemas[schema_name]
        except KeyError as exc:
            raise RecordError(f"unregistered local schema: {schema_name!r}") from exc
        return Draft202012Validator(
            schema,
            registry=self._checked_registry,
            format_checker=Draft202012Validator.FORMAT_CHECKER,
        )

    def validate(self, instance: Any, schema_name: str) -> None:
        """Validate an in-memory instance and report deterministic locations."""

        try:
            errors = sorted(
                self.validator(schema_name).iter_errors(instance),
                key=lambda error: (_stable_path(error.absolute_path), _stable_path(error.absolute_schema_path), error.message),
            )
        except RecursionError as exc:
            raise RecordError(f"{schema_name} validation exceeded the supported schema recursion") from exc
        if errors:
            shown = errors[:10]
            details = "; ".join(f"{_stable_path(error.absolute_path)}: {error.message}" for error in shown)
            omitted = len(errors) - len(shown)
            if omitted:
                details += f"; ... {omitted} additional validation error(s)"
            raise RecordError(f"{schema_name} rejected the JSON instance with {len(errors)} error(s): {details}")


_CacheKey = tuple[str, tuple[tuple[str, str], ...]]
_CATALOG_CACHE: dict[_CacheKey, LocalSchemaCatalog] = {}
_CATALOG_CACHE_LOCK = threading.Lock()
_CATALOG_CACHE_LIMIT = 64


def clear_schema_catalog_cache() -> None:
    """Drop every memoised catalog; the next load re-checks from bytes."""

    with _CATALOG_CACHE_LOCK:
        _CATALOG_CACHE.clear()


def _read_schema_files(schema_dir: Path) -> tuple[tuple[Path, bytes], ...]:
    if not isinstance(schema_dir, Path):
        raise TypeError("schema_dir must be pathlib.Path")
    paths = tuple(sorted(schema_dir.glob("*.schema.json")))
    if not paths:
        raise RecordError(f"no local JSON schemas found in {schema_dir}")
    sources = []
    for path in paths:
        try:
            sources.append((path, path.read_bytes()))
        except OSError as exc:
            raise RecordError(f"cannot read {path}: {exc}") from exc
    return tuple(sources)


def load_local_schema_catalog(schema_dir: Path = DEFAULT_SCHEMA_DIR) -> LocalSchemaCatalog:
    """Strict-load and check every ``*.schema.json`` file in one directory."""

    sources = _read_schema_files(schema_dir)
    cache_key: _CacheKey = (str(schema_dir), tuple((path.name, bytes_digest(raw)) for path, raw in sources))
    with _CATALOG_CACHE_LOCK:
        cached = _CATALOG_CACHE.get(cache_key)
    if cached is not None:
        return cached

    parsed: dict[str, dict[str, Any]] = {}
    schema_ids: set[str] = set()
    for path, raw_bytes in sources:
        try:
            source = raw_bytes.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise RecordError(f"JSON is not UTF-8: {path}") from exc
        raw = loads_strict(source)
        if type(raw) is not dict:
            raise RecordError(f"schema must be a JSON object: {path}")
        if raw.get("$schema") != _DRAFT_2020_12:
            raise RecordError(f"schema must declare JSON Schema 2020-12: {path}")
        schema_id = raw.get("$id")
        if type(schema_id) is not str or not schema_id:
            raise RecordError(f"schema must declare a non-empty $id: {path}")
        try:
            parsed_id = urlsplit(schema_id)
        except ValueError as exc:
            raise RecordError(f"invalid schema $id URI: {path}") from exc
        if not parsed_id.scheme or parsed_id.fragment:
            raise RecordError(f"schema $id must be absolute and fragment-free: {path}")
        if schema_id in schema_ids:
            raise RecordError(f"duplicate schema $id: {schema_id}")
        try:
            Draft202012Validator.check_schema(raw)
        except SchemaError as exc:
            raise RecordError(f"invalid JSON Schema {path}: {exc}") from exc
        parsed[path.name] = raw
        schema_ids.add(schema_id)

    try:
        registry = _registry_from_schemas(parsed)
    except CannotDetermineSpecification as exc:
        raise RecordError(f"schema registry could not be built: {exc}") from exc
    reference_errors = (InvalidAnchor, NoSuchAnchor, NoSuchResource, PointerToNowhere, Unresolvable, Unretrievable, ValueError)
    for schema_name, schema in parsed.items():
        root_id = schema["$id"]
        for base_uri, reference in _schema_references(schema, root_id):
            try:
                registry.resolver(base_uri).lookup(reference)
            except reference_errors as exc:
                try:
                    resolved = urljoin(base_uri, reference)
                except ValueError:
                    resolved = reference
                raise RecordError(f"schema {schema_name} has an unregistered or invalid local reference {resolved!r}") from exc

    catalog = LocalSchemaCatalog(
        schema_dir=schema_dir,
        _schema_sources=MappingProxyType(
            {name: json.dumps(schema, ensure_ascii=False, sort_keys=True, separators=(",", ":")) for name, schema in sorted(parsed.items())}
        ),
        _checked_schemas=MappingProxyType({name: parsed[name] for name in sorted(parsed)}),
        _checked_registry=registry,
    )
    with _CATALOG_CACHE_LOCK:
        if len(_CATALOG_CACHE) >= _CATALOG_CACHE_LIMIT:
            _CATALOG_CACHE.clear()
        return _CATALOG_CACHE.setdefault(cache_key, catalog)

